{"command":"python3 - << 'PY'
import subprocess, os, json
EXE=os.path.abspath("./executable")
def get(inp, fmt="rustc-json", extra=[]):
 p=subprocess.run([EXE,"-","--error-format",fmt]+extra,input=inp,capture_output=True,text=True)
 for line in p.stderr.splitlines():
   try:
     j=json.loads(line)
     if 'children' in j:
       j2={k:v for k,v in j.items() if k!='rendered'}
       print(json.dumps(j2,indent=2))
       print("RENDERED:\n"+(j.get('rendered') or ''))
     else:
       j2={k:v for k,v in j.items() if k!='formattedMessage'}
       print(json.dumps(j2,indent=2)); print("FORMATTED:\n"+j.get('formattedMessage',''))
   except Exception as e: print("nonjson",line)
for inp in [
"interface I{ function f() external; } contract C is I{}",
"library L{ function f() public; }",
"contract C{ uint x = `; }",
]:
 print("=====",inp); get(inp); get(inp,"json")
PY"}

