# ============================= CLI parsing =============================
class CliExit(Exception):
    def __init__(self, code, stdout="", stderr=""):
        self.code=code; self.stdout=stdout; self.stderr=stderr

@dataclass
class ZFlags:
    ui_testing: bool=False
    track_diagnostics: bool=False
    parse_yul: bool=False
    no_resolve_imports: bool=False
    dump: object=None  # tuple(kind, list_of_paths or None)
    ast_stats: bool=False
    span_visitor: bool=False
    print_max_storage_sizes: bool=False
    typeck: bool=False
    help: bool=False
    raw: list=field(default_factory=list)

@dataclass
class Opts:
    inputs: list=field(default_factory=list)
    remappings: list=field(default_factory=list)  # (context, prefix, path, original)
    threads: int=0
    evm_version: str="prague"
    stop_after: object=None
    out_dir: object=None
    emit: list=field(default_factory=list)
    z: ZFlags=field(default_factory=ZFlags)
    base_path: object=None
    include_paths: list=field(default_factory=list)
    allow_paths: list=field(default_factory=list)
    language: str="solidity"
    color: str="auto"
    verbose: bool=False
    pretty_json: bool=False
    pretty_json_err: bool=False
    error_format: str="human"
    error_format_human: str="unicode"
    diagnostic_width: object=None
    no_warnings: bool=False

class _Opt:
    def __init__(self,key,longs,short,value_name,kind,possible=None,multiple=False):
        self.key=key; self.longs=longs; self.short=short; self.value_name=value_name; self.kind=kind; self.possible=possible; self.multiple=multiple
    @property
    def display(self):
        if self.key=="unstable": return "-Z <FLAG>"
        return "--"+self.longs[0]+((" <"+self.value_name+">") if self.value_name else "")
    usage = display

_EVM=["homestead","tangerineWhistle","spuriousDragon","byzantium","constantinople","petersburg","istanbul","berlin","london","paris","shanghai","cancun","prague","osaka"]
_OPTS=[
 _Opt("threads",["threads","jobs"],"j","THREADS","int"),
 _Opt("evm_version",["evm-version"],None,"EVM_VERSION","enum",_EVM),
 _Opt("stop_after",["stop-after"],None,"STOP_AFTER","enum",["parsing","lowering","analysis"]),
 _Opt("out_dir",["out-dir"],None,"OUT_DIR","path"),
 _Opt("emit",["emit"],None,"EMIT","emit",["abi","hashes"],True),
 _Opt("unstable",[],"Z","FLAG","z",None,True),
 _Opt("help",["help"],"h",None,"help"),
 _Opt("version",["version"],"V",None,"version"),
 _Opt("base_path",["base-path"],None,"BASE_PATH","path"),
 _Opt("include_path",["include-path"],"I","INCLUDE_PATH","path",None,True),
 _Opt("allow_paths",["allow-paths"],None,"ALLOW_PATHS","path",None,True),
 _Opt("language",["language"],None,"LANGUAGE","enum",["solidity","yul"]),
 _Opt("color",["color"],None,"COLOR","enum",["auto","always","never"]),
 _Opt("verbose",["verbose"],"v",None,"bool"),
 _Opt("pretty_json",["pretty-json"],None,None,"bool"),
 _Opt("pretty_json_err",["pretty-json-err"],None,None,"bool"),
 _Opt("error_format",["error-format"],None,"ERROR_FORMAT","enum",["human","json","rustc-json"]),
 _Opt("error_format_human",["error-format-human"],None,"VALUE","enum",["ascii","unicode","short"]),
 _Opt("diagnostic_width",["diagnostic-width"],None,"WIDTH","int"),
 _Opt("no_warnings",["no-warnings"],None,None,"bool"),
]
_LONG={l:o for o in _OPTS for l in o.longs}
_SHORT={o.short:o for o in _OPTS if o.short}
_BOOLKEYS={"verbose","pretty_json","pretty_json_err","no_warnings"}

_MEGA_USAGE="<INPUT|--base-path <BASE_PATH>|--include-path <INCLUDE_PATH>|--allow-paths <ALLOW_PATHS>|--language <LANGUAGE>|--threads <THREADS>|--evm-version <EVM_VERSION>|--stop-after <STOP_AFTER>|--out-dir <OUT_DIR>|--emit <EMIT>|--color <COLOR>|--verbose|--pretty-json|--pretty-json-err|--error-format <ERROR_FORMAT>|--error-format-human <VALUE>|--diagnostic-width <WIDTH>|--no-warnings|-Z <FLAG>>"

def _parse_usize(s, opt):
    # Rust usize FromStr
    if s=="":
        raise CliExit(2,stderr=f"error: invalid value '' for '{opt.display}': cannot parse integer from empty string\n\nFor more information, try '--help'.\n")
    t=s[1:] if s.startswith("+") else s
    if t=="" or not all('0'<=c<='9' for c in t):
        raise CliExit(2,stderr=f"error: invalid value '{s}' for '{opt.display}': invalid digit found in string\n\nFor more information, try '--help'.\n")
    v=int(t)
    if v>18446744073709551615:
        raise CliExit(2,stderr=f"error: invalid value '{s}' for '{opt.display}': number too large to fit in target type\n\nFor more information, try '--help'.\n")
    return v

def _possible_str(vals):
    return "  [possible values: "+", ".join(vals)+"]\n" if vals else ""

def parse_cli(argv):
    prog=prog_name()
    if len(argv)==0 or argv==["--"]:
        raise CliExit(2,stderr=help_short(prog))
    opts=Opts(); opts.threads=default_threads()
    counts={}          # key -> occurrences
    used=[]            # keys in order
    bool_seen=False
    pending=None       # [opt, raw_value]
    inputs=[]          # positional strings
    positional_seen=False
    end=False

    def note_used(opt):
        if opt.key not in used: used.append(opt.key)
        counts[opt.key]=counts.get(opt.key,0)+1

    def usage_for_unexpected(suggested_opt=None):
        if suggested_opt is not None:
            items=[]
            for k in used:
                o=next(x for x in _OPTS if x.key==k)
                if not o.multiple and counts.get(k,0)>1: continue
                items.append(o.display)
            if suggested_opt.display not in items: items.append(suggested_opt.display)
            suffix="<INPUT>..." if positional_seen else "[INPUT]..."
            return "Usage: "+prog+" "+" ".join(items+[" "+suffix]) if False else "Usage: "+prog+" "+" ".join(items)+" "+suffix+"\n"
        items=[]
        for k in used:
            o=next(x for x in _OPTS if x.key==k)
            if not o.multiple and counts.get(k,0)>1: continue
            items.append(o.display)
        if not items and not positional_seen:
            return f"Usage: {prog} [OPTIONS] [INPUT]...\n"
        suffix="<INPUT>..." if positional_seen else "[INPUT]..."
        if items: return "Usage: "+prog+" "+" ".join(items)+" "+suffix+"\n"
        return "Usage: "+prog+" "+suffix+"\n"

    def multiple_error(opt):
        raise CliExit(2,stderr=f"error: the argument '{opt.display}' cannot be used multiple times\n\nUsage: {prog} [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n")

    def missing_error(opt):
        raise CliExit(2,stderr=f"error: a value is required for '{opt.display}' but none was supplied\n"+_possible_str(opt.possible)+f"\nFor more information, try '--help'.\n")

    def invalid_value(opt, val):
        msg=f"error: invalid value '{val}' for '{opt.display}'\n"+_possible_str(opt.possible)
        if opt.possible:
            sim=did_you_mean(val, opt.possible)
            if sim: msg+=f"\n  tip: a similar value exists: '{sim}'\n"
        msg+=f"\nFor more information, try '--help'.\n"
        raise CliExit(2,stderr=msg)

    def apply_value(opt, val, check_multiple=True):
        # empty handling
        if opt.kind=="int":
            v=_parse_usize(val,opt)
        else:
            if val=="":
                missing_error(opt)
            v=val
        if check_multiple and not opt.multiple and counts.get(opt.key,0)>1:
            multiple_error(opt)
        # validate
        if opt.kind=="enum":
            if val not in opt.possible: invalid_value(opt,val)
            v=val
        elif opt.kind=="emit":
            parts=val.split(",")
            for part in parts:
                if part=="": missing_error(opt)
            for part in parts:
                if part not in opt.possible: invalid_value(opt,part)
            v=parts
