            if kind not in ("ast","hir"):
                _z_error(f"invalid value '{val}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found\n\nFor more information, try '-Zhelp'.")
            z.dump=(kind,paths)
            continue
        # boolean Z flags
        if has_val:
            _z_error(f"unexpected value '{val}' for '-Z{name}' found; no more were expected\n\nUsage: solar -Z{name}\n\nFor more information, try '-Zhelp'.")
