# ============================= CLI parsing =============================
class CliExit(Exception):
    def __init__(self, code, stdout="", stderr=""):
        self.code=code; self.stdout=stdout; self.stderr=stderr

@dataclass
class ZFlags:
    ui_testing: bool=False
    track_diagnostics: bool=False
    parse_yul: bool=False
    no_resolve_imports: bool=False
    dump: object=None  # tuple(kind, list_of_paths or None)
    ast_stats: bool=False
    span_visitor: bool=False
    print_max_storage_sizes: bool=False
    typeck: bool=False
    help: bool=False
    raw: list=field(default_factory=list)

@dataclass
class Opts:
    inputs: list=field(default_factory=list)
    remappings: list=field(default_factory=list)  # (context, prefix, path, original)
    threads: int=0
    evm_version: str="prague"
    stop_after: object=None
    out_dir: object=None
    emit: list=field(default_factory=list)
    z: ZFlags=field(default_factory=ZFlags)
    base_path: object=None
    include_paths: list=field(default_factory=list)
    allow_paths: list=field(default_factory=list)
    language: str="solidity"
    color: str="auto"
    verbose: bool=False
    pretty_json: bool=False
    pretty_json_err: bool=False
    error_format: str="human"
    error_format_human: str="unicode"
    diagnostic_width: object=None
    no_warnings: bool=False

class _Opt:
    def __init__(self,key,longs,short,value_name,kind,possible=None,multiple=False):
        self.key=key; self.longs=longs; self.short=short; self.value_name=value_name; self.kind=kind; self.possible=possible; self.multiple=multiple
    @property
    def display(self):
        if self.key=="unstable": return "-Z <FLAG>"
        return "--"+self.longs[0]+((" <"+self.value_name+">") if self.value_name else "")
    usage = display

_EVM=["homestead","tangerineWhistle","spuriousDragon","byzantium","constantinople","petersburg","istanbul","berlin","london","paris","shanghai","cancun","prague","osaka"]
_OPTS=[
 _Opt("threads",["threads","jobs"],"j","THREADS","int"),
 _Opt("evm_version",["evm-version"],None,"EVM_VERSION","enum",_EVM),
 _Opt("stop_after",["stop-after"],None,"STOP_AFTER","enum",["parsing","lowering","analysis"]),
 _Opt("out_dir",["out-dir"],None,"OUT_DIR","path"),
 _Opt("emit",["emit"],None,"EMIT","emit",["abi","hashes"],True),
 _Opt("unstable",[],"Z","FLAG","z",None,True),
 _Opt("help",["help"],"h",None,"help"),
 _Opt("version",["version"],"V",None,"version"),
 _Opt("base_path",["base-path"],None,"BASE_PATH","path"),
 _Opt("include_path",["include-path"],"I","INCLUDE_PATH","path",None,True),
 _Opt("allow_paths",["allow-paths"],None,"ALLOW_PATHS","path",None,True),
 _Opt("language",["language"],None,"LANGUAGE","enum",["solidity","yul"]),
 _Opt("color",["color"],None,"COLOR","enum",["auto","always","never"]),
 _Opt("verbose",["verbose"],"v",None,"bool"),
 _Opt("pretty_json",["pretty-json"],None,None,"bool"),
 _Opt("pretty_json_err",["pretty-json-err"],None,None,"bool"),
 _Opt("error_format",["error-format"],None,"ERROR_FORMAT","enum",["human","json","rustc-json"]),
 _Opt("error_format_human",["error-format-human"],None,"VALUE","enum",["ascii","unicode","short"]),
 _Opt("diagnostic_width",["diagnostic-width"],None,"WIDTH","int"),
 _Opt("no_warnings",["no-warnings"],None,None,"bool"),
]
_LONG={l:o for o in _OPTS for l in o.longs}
_SHORT={o.short:o for o in _OPTS if o.short}
_BOOLKEYS={"verbose","pretty_json","pretty_json_err","no_warnings"}

_MEGA_USAGE="<INPUT|--base-path <BASE_PATH>|--include-path <INCLUDE_PATH>|--allow-paths <ALLOW_PATHS>|--language <LANGUAGE>|--threads <THREADS>|--evm-version <EVM_VERSION>|--stop-after <STOP_AFTER>|--out-dir <OUT_DIR>|--emit <EMIT>|--color <COLOR>|--verbose|--pretty-json|--pretty-json-err|--error-format <ERROR_FORMAT>|--error-format-human <VALUE>|--diagnostic-width <WIDTH>|--no-warnings|-Z <FLAG>>"

def _parse_usize(s, opt):
    # Rust usize FromStr
    if s=="":
        raise CliExit(2,stderr=f"error: invalid value '' for '{opt.display}': cannot parse integer from empty string\n\nFor more information, try '--help'.\n")
    t=s[1:] if s.startswith("+") else s
    if t=="" or not all('0'<=c<='9' for c in t):
        raise CliExit(2,stderr=f"error: invalid value '{s}' for '{opt.display}': invalid digit found in string\n\nFor more information, try '--help'.\n")
    v=int(t)
    if v>18446744073709551615:
        raise CliExit(2,stderr=f"error: invalid value '{s}' for '{opt.display}': number too large to fit in target type\n\nFor more information, try '--help'.\n")
    return v

def _possible_str(vals):
    return "  [possible values: "+", ".join(vals)+"]\n" if vals else ""

def parse_cli(argv):
    prog=prog_name()
    if len(argv)==0 or argv==["--"]:
        raise CliExit(2,stderr=help_short(prog))
    opts=Opts(); opts.threads=default_threads()
    counts={}          # key -> occurrences
    used=[]            # keys in order
    bool_seen=False
    pending=None       # [opt, raw_value]
    inputs=[]          # positional strings
    positional_seen=False
    end=False

    def note_used(opt):
        if opt.key not in used: used.append(opt.key)
        counts[opt.key]=counts.get(opt.key,0)+1

    def usage_for_unexpected(suggested_opt=None):
        if suggested_opt is not None:
            items=[]
            for k in used:
                o=next(x for x in _OPTS if x.key==k)
                if not o.multiple and counts.get(k,0)>1: continue
                items.append(o.display)
            if suggested_opt.display not in items: items.append(suggested_opt.display)
            suffix="<INPUT>..." if positional_seen else "[INPUT]..."
            return "Usage: "+prog+" "+" ".join(items+[" "+suffix]) if False else "Usage: "+prog+" "+" ".join(items)+" "+suffix+"\n"
        items=[]
        for k in used:
            o=next(x for x in _OPTS if x.key==k)
            if not o.multiple and counts.get(k,0)>1: continue
            items.append(o.display)
        if not items and not positional_seen:
            return f"Usage: {prog} [OPTIONS] [INPUT]...\n"
        suffix="<INPUT>..." if positional_seen else "[INPUT]..."
        if items: return "Usage: "+prog+" "+" ".join(items)+" "+suffix+"\n"
        return "Usage: "+prog+" "+suffix+"\n"

    def multiple_error(opt):
        raise CliExit(2,stderr=f"error: the argument '{opt.display}' cannot be used multiple times\n\nUsage: {prog} [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n")

    def missing_error(opt):
        raise CliExit(2,stderr=f"error: a value is required for '{opt.display}' but none was supplied\n"+_possible_str(opt.possible)+f"\nFor more information, try '--help'.\n")

    def invalid_value(opt, val):
        msg=f"error: invalid value '{val}' for '{opt.display}'\n"+_possible_str(opt.possible)
        if opt.possible:
            sim=did_you_mean(val, opt.possible)
            if sim: msg+=f"\n  tip: a similar value exists: '{sim}'\n"
        msg+=f"\nFor more information, try '--help'.\n"
        raise CliExit(2,stderr=msg)

    def apply_value(opt, val, check_multiple=True):
        # empty handling
        if opt.kind=="int":
            v=_parse_usize(val,opt)
        else:
            if val=="":
                missing_error(opt)
            v=val
        if check_multiple and not opt.multiple and counts.get(opt.key,0)>1:
            multiple_error(opt)
        # validate
        if opt.kind=="enum":
            if val not in opt.possible: invalid_value(opt,val)
            v=val
        elif opt.kind=="emit":
            parts=val.split(",")
            for part in parts:
                if part=="": missing_error(opt)
            for part in parts:
                if part not in opt.possible: invalid_value(opt,part)
            v=parts
        # store
        if opt.key=="threads": opts.threads=v
        elif opt.key=="diagnostic_width": opts.diagnostic_width=v
        elif opt.key=="emit": opts.emit.extend(v)
        elif opt.key=="include_path": opts.include_paths.append(v)
        elif opt.key=="allow_paths": opts.allow_paths.append(v)
        elif opt.key=="unstable": opts.z.raw.append(v)
        else: setattr(opts,opt.key,v)

    def finalize_pending():
        nonlocal pending
        if pending is not None:
            opt,val=pending; pending=None
            apply_value(opt,val,check_multiple=True)

    def unexpected_argument(tok_display, orig_tok, is_long):
        # suggestions
        suggested=None; sim=None
        if is_long:
            name=orig_tok[2:].split("=",1)[0]
            cands=[]
            for o in _OPTS:
                cands.extend(o.longs)
            sim=did_you_mean(name,cands)
            if sim: suggested=_LONG.get(sim)
        if suggested is not None:
            tip=f"  tip: a similar argument exists: '--{sim}'\n"
        else:
            tip=f"  tip: to pass '{tok_display}' as a value, use '-- {tok_display}'\n"
        raise CliExit(2,stderr=f"error: unexpected argument '{tok_display}' found\n\n"+tip+f"\n"+usage_for_unexpected(suggested)+f"\nFor more information, try '--help'.\n")

    def is_known_flag(tok):
        if tok=="--": return True
        if tok.startswith("--"):
            return tok[2:].split("=",1)[0] in _LONG
        if tok.startswith("-") and len(tok)>1:
            return tok[1] in _SHORT
        return False

    def is_flaglike(tok):
        return len(tok)>1 and tok.startswith("-")

    i=0
    while i<len(argv):
        tok=argv[i]
        if end:
            finalize_pending(); inputs.append(tok); positional_seen=True; i+=1; continue
        if tok=="--":
            finalize_pending(); end=True; i+=1; continue
        if tok=="-" or tok=="" or not tok.startswith("-"):
            finalize_pending(); inputs.append(tok); positional_seen=True; i+=1; continue
        if tok.startswith("--"):
            body=tok[2:]; has_eq="=" in body
            name=body.split("=",1)[0] if has_eq else body
            eqval=body.split("=",1)[1] if has_eq else None
            opt=_LONG.get(name)
            if opt is None:
                # unknown long preempts pending
                disp="--"+name if name else "--"
                unexpected_argument(disp,tok,True)
            # known token finalizes pending first
            finalize_pending()
            if opt.kind=="help":
                if has_eq:
                    raise CliExit(2,stderr=f"error: unexpected value '{eqval}' for '--help' found; no more were expected\n\nUsage: {prog} --help [INPUT]...\n\nFor more information, try '--help'.\n")
                raise CliExit(0,stdout=help_long(prog))
            if opt.kind=="version":
                if has_eq:
                    raise CliExit(2,stderr=f"error: unexpected value '{eqval}' for '--version' found; no more were expected\n\nUsage: {prog} --version [INPUT]...\n\nFor more information, try '--help'.\n")
                raise CliExit(0,stdout=VERSION_LONG)
            if opt.kind=="bool":
                if has_eq:
                    if bool_seen:
                        usage=f"Usage: {prog} {_MEGA_USAGE}\n"
                    else:
                        usage=f"Usage: {prog} {opt.display} [INPUT]...\n"
                    raise CliExit(2,stderr=f"error: unexpected value '{eqval}' for '{opt.display}' found; no more were expected\n\n"+usage+f"\nFor more information, try '--help'.\n")
                note_used(opt)
                if counts[opt.key]>1: multiple_error(opt)
                setattr(opts,opt.key,True); bool_seen=True; i+=1; continue
            # value option (long)
            note_used(opt)
            if has_eq:
                apply_value(opt,eqval,check_multiple=True); i+=1; continue
            # separated value
            if i+1>=len(argv):
                counts[opt.key]-=1  # not used (for any future) - error has no usage
                missing_error(opt)
            nxt=argv[i+1]
            if is_flaglike(nxt):
                if nxt=="--" or is_known_flag(nxt):
                    missing_error(opt)
                else:
                    # unknown flag: report it. Current opt counts as used? clap usage generic;
                    counts[opt.key]-=1
                    if opt.key in used and counts.get(opt.key,0)==0: used.remove(opt.key)
                    # dispatch unknown handling
                    if nxt.startswith("--"):
                        nm=nxt[2:].split("=",1)[0]; unexpected_argument("--"+nm if nm else "--",nxt,True)
                    else:
                        # short cluster
                        if len(nxt)>2 and nxt[1].isalpha(): disp="-"+nxt[1]
                        else: disp=nxt
                        unexpected_argument(disp,nxt,False)
            pending=[opt,nxt]; i+=2; continue
        # short cluster
        # unknown first char preempts pending
        first=tok[1] if len(tok)>1 else ""
        if first not in _SHORT:
            if len(tok)>2 and first.isalpha(): disp="-"+first
            else: disp=tok
            unexpected_argument(disp,tok,False)
        finalize_pending()
        j=1
        while j<len(tok):
            ch=tok[j]; opt=_SHORT.get(ch)
            if opt is None:
                # e.g. -v=... : '=' becomes - =
                disp="-"+ch if ch.isalpha() else "-"+ch
                # For -v=true, clap reports '-='
                if ch=="=": disp="-="
                unexpected_argument(disp,tok,False)
            if opt.kind=="help":
                raise CliExit(0,stdout=help_short(prog))
            if opt.kind=="version":
                raise CliExit(0,stdout=VERSION_SHORT)
            if opt.kind=="bool":
                note_used(opt)
                if counts[opt.key]>1: multiple_error(opt)
                setattr(opts,opt.key,True); bool_seen=True; j+=1; continue
            # value-taking short: -j, -I, -Z
            note_used(opt)
            rest=tok[j+1:]
            if opt.key=="threads" and counts.get(opt.key,0)>1:
                multiple_error(opt)
            if rest!="":
                val=rest[1:] if rest.startswith("=") else rest
                # clap: -j= gives invalid '' int; -I= gives missing; -Z= gives raw '' / ...
                if opt.key=="unstable":
                    # preserve leading '=' info by passing raw rest (-Z=help -> '=help')
                    apply_value(opt,rest,check_multiple=False)
                else:
                    apply_value(opt,val,check_multiple=True)
                j=len(tok); break
            else:
                if i+1>=len(argv): missing_error(opt)
                nxt=argv[i+1]
                if is_flaglike(nxt):
                    if nxt=="--" or is_known_flag(nxt): missing_error(opt)
                    else:
                        counts[opt.key]-=1
                        if opt.key in used and counts.get(opt.key,0)==0: used.remove(opt.key)
                        if nxt.startswith("--"):
                            nm=nxt[2:].split("=",1)[0]; unexpected_argument("--"+nm if nm else "--",nxt,True)
                        else:
                            disp="-"+nxt[1] if len(nxt)>2 and nxt[1].isalpha() else nxt
                            unexpected_argument(disp,nxt,False)
                apply_value(opt,nxt,check_multiple=True)
                i+=1; j=len(tok); break
        i+=1
    finalize_pending()
    opts.inputs=inputs
    # parse remappings out of inputs
    real_inputs=[]
    for inp in inputs:
        if "=" in inp:
            left,path=inp.split("=",1)
            if ":" in left:
                context,prefix=left.split(":",1)
            else:
                context,prefix=None,left
            if prefix=="":
                raise CliExit(2,stderr=f"error: invalid remapping {rust_debug_str(inp)}: empty prefix\n\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n")
            opts.remappings.append((context,prefix,path,inp))
        else:
            real_inputs.append(inp)
    opts.inputs=real_inputs
    # parse -Z flags
    parse_z_flags(opts)
    return opts

Z_FLAG_NAMES=["ui-testing","track-diagnostics","parse-yul","no-resolve-imports","dump","ast-stats","span-visitor","print-max-storage-sizes","typeck","help"]
def _z_error(inner):
    raise CliExit(2,stderr="error:  "+inner+"\n\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n")

def parse_z_flags(opts):
    z=opts.z; seen={}
    for raw in z.raw:
        # raw is the part after -Z; for -Z=foo forms, raw starts with '='
        if raw=="":
            continue
        tok="-Z"+raw  # reconstructed token e.g. -Zui-testing / -Z=help
        nameval=raw[1:] if raw.startswith("=") else raw
        if raw.startswith("=="):
            _z_error("unexpected argument '-Z' found\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.")
        if "=" in nameval:
            name,val=nameval.split("=",1); has_val=True
        else:
            name,val=nameval,None; has_val=False
        if name not in Z_FLAG_NAMES:
            disp="-Z"+nameval
            cands=["-Z"+n for n in ["ui-testing","track-diagnostics","parse-yul","no-resolve-imports","ast-stats","span-visitor","print-max-storage-sizes","typeck","help"]]
            sim=did_you_mean(disp,cands)
            if sim:
                _z_error(f"unexpected argument '{disp}' found\n\n  tip: a similar argument exists: '{sim}'\n\nUsage: solar {sim}\n\nFor more information, try '-Zhelp'.")
            else:
                _z_error(f"unexpected argument '{disp}' found\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.")
        if name=="help":
            if has_val:
                _z_error(f"unexpected value '{val}' for '-Zhelp' found; no more were expected\n\nUsage: solar -Zhelp\n\nFor more information, try '-Zhelp'.")
            raise CliExit(0,stdout=Z_HELP)
        if name=="dump":
            if not has_val:
                _z_error("equal sign is needed when assigning values to '-Zdump=<KIND[=PATHS...]>'\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.")
            if "dump" in seen:
                _z_error("the argument '-Zdump=<KIND[=PATHS...]>' cannot be used multiple times\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.")
            seen["dump"]=True
            # val: KIND[=PATHS...] where PATHS comma separated
            if val=="":
                _z_error("invalid value '' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found\n\nFor more information, try '-Zhelp'.")
            if "=" in val:
                kind,paths_s=val.split("=",1); paths=paths_s.split(",")
            else:
                kind,paths=val,None
            if kind not in ("ast","hir"):
                _z_error(f"invalid value '{val}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found\n\nFor more information, try '-Zhelp'.")
            z.dump=(kind,paths)
            continue
        # boolean Z flags
        if has_val:
            _z_error(f"unexpected value '{val}' for '-Z{name}' found; no more were expected\n\nUsage: solar -Z{name}\n\nFor more information, try '-Zhelp'.")
        if name in seen:
            _z_error(f"the argument '-Z{name}' cannot be used multiple times\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.")
        seen[name]=True
        setattr(z,name.replace("-","_"),True)

PYEOF
python3 -m py_compile solar.py && echo ok"}

