def _c(text,style,color):
    if not color or text=="": return text
    if style=="margin": return f"\x1b[1m\x1b[94m{text}\x1b[0m"
    if style=="bold": return f"\x1b[1m{text}\x1b[0m"
    if style.startswith("lvl:"):
        return f"\x1b[1m\x1b[{LEVEL_COLOR.get(style[4:],'91')}m{text}\x1b[0m"
    return text

