        # color decision
        self.color_enabled=self._decide_color()
        self.renderer=DiagRenderer(sources,style=("short" if opts.error_format_human=="short" else opts.error_format_human),color=self.color_enabled,width=opts.diagnostic_width,ui_testing=opts.z.ui_testing)
    def _decide_color(self):
        if self.opts.color=="always": return True
        if self.opts.color=="never": return False
        # auto: anstream-like
        if os.environ.get("CLICOLOR_FORCE") not in (None,"","0"):
            # still NO_COLOR? supports-color precedence tested partially; NO_COLOR checked below first in original? Force may override. approximate:
            if os.environ.get("NO_COLOR"):
                pass
            else:
                return True
        if os.environ.get("NO_COLOR"): return False
        if os.environ.get("TERM")=="dumb": return False
        if os.environ.get("CLICOLOR")=="0": return False
        try: return sys.stderr.isatty()
        except Exception: return False
    def emit(self,diag):
        if diag.level=="error": self.errors+=1
        if diag.level=="warning":
            self.warnings+=1
            if self.opts.no_warnings: return
        # track diagnostics
        if self.opts.z.track_diagnostics and diag.created:
            created,emitted=diag.created
            diag.children.append(Diag("note",f"created at {created},\nemitted at {emitted}"))
        self.emitted.append(diag)
        # render & write to stderr immediately (important ordering vs stdout unflushed? Python stdout buffered separately; callers flush stdout before diagnostics in some phases)
        sys.stdout.flush()
        text=self.format_diag(diag)
        sys.stderr.write(text); sys.stderr.flush()
    def format_diag(self,diag):
        fmt=self.opts.error_format
        if fmt=="human":
            return self.renderer.render(diag)
        elif fmt=="rustc-json":
            obj=self.to_rustc_json(diag,top=True)
            if self.opts.pretty_json_err:
                return json.dumps(obj,indent=2,ensure_ascii=False)+"\n"
            return json.dumps(obj,separators=(",",":"),ensure_ascii=False)+"\n"
        elif fmt=="json":
            obj=self.to_solc_json(diag)
            if self.opts.pretty_json_err:
                return json.dumps(obj,indent=2,ensure_ascii=False)+"\n"
            return json.dumps(obj,separators=(",",":"),ensure_ascii=False)+"\n"
        return self.renderer.render(diag)
    def aborting(self):
        n=self.errors
        if n==1: msg="aborting due to 1 previous error"
        else: msg=f"aborting due to {n} previous errors"
        d=Diag("error",msg)
        # emit manually without counting
        sys.stdout.flush()
        sys.stderr.write(self.format_diag(d)); sys.stderr.flush()
    # ---- JSON conversions
    def span_rustc(self,s):
        src=self.sources[s.fid]
        ls,cs=src.line_col(s.lo)
        le,ce=src.line_col(s.hi)
        texts=[]
        if src.text!="":
            sl=src.line_index(s.lo); el=src.line_index(s.hi-1) if s.hi>s.lo else src.line_index(s.hi)
            # For spans ending at a newline, rustc includes two text entries (start line & end line col1)
            # Determine end line by line_col(hi): if hi is at line start and hi>lo, include that line too
            end_line_for_text=src.line_index(s.hi) if s.hi>len(src.text) else src.line_index(min(s.hi,len(src.text)))
            # rustc logic: iterate lines from ls-1 to le-1 based on line_col endpoints
            for li in range(ls-1, max(ls-1,le-1)+1):
                if li<0: continue
                # line_col line_end could be past last line if hi at EOF after newline
                if li>=len(src.line_starts): continue
                raw=src.line_text(li)
                lstart,_=src.line_bounds(li)
                hs=(s.lo-lstart+1) if li==ls-1 else 1
                he=(s.hi-lstart+1) if li==le-1 else (len(raw)+1)
                # For line before end if hi at start of next line, he on prev line is len+1
                texts.append({"text":raw,"highlight_start":hs,"highlight_end":he})
        return {"file_name":src.name,"byte_start":src.byte(s.lo),"byte_end":src.byte(s.hi),"line_start":ls,"line_end":le,"column_start":cs,"column_end":ce,"is_primary":s.is_primary,"text":texts,"label":s.label,"suggested_replacement":s.suggested}
    def to_rustc_json(self,diag,top=False):
        obj={}
        if top: obj["$message_type"]="diagnostic"
        obj["message"]=diag.msg
        obj["code"]=({"code":str(diag.code),"explanation":None} if diag.code else None)
        obj["level"]=diag.level
        obj["spans"]=[self.span_rustc(s) for s in diag.spans if 0<=s.fid<len(self.sources)]
        obj["children"]=[self.to_rustc_child(c) for c in diag.children]
        obj["rendered"]=self.renderer.render(diag) if top else None
        return obj
    def to_rustc_child(self,diag):
        return {"message":diag.msg,"code":({"code":str(diag.code),"explanation":None} if diag.code else None),"level":diag.level,"spans":[self.span_rustc(s) for s in diag.spans if 0<=s.fid<len(self.sources)],"children":[self.to_rustc_child(c) for c in diag.children],"rendered":None}
    def to_solc_json(self,diag):
        # primary span
        prim=None
        for s in diag.spans:
            if s.is_primary: prim=s; break
        if prim is None and diag.spans: prim=diag.spans[0]
        if prim is not None and 0<=prim.fid<len(self.sources):
            src=self.sources[prim.fid]
            source_loc={"file":src.name,"start":src.byte(prim.lo),"end":src.byte(prim.hi)}
            primary_file=src.name
        else:
            source_loc=None; primary_file=""
        secondary=[]
        def walk(children):
            for child in children:
                spanful=[s for s in child.spans if 0<=s.fid<len(self.sources) and s.suggested is None]
                if spanful:
                    for s in spanful:
                        src=self.sources[s.fid]
                        secondary.append({"file":src.name,"start":src.byte(s.lo),"end":src.byte(s.hi),"message":child.msg})
                elif not any(s.suggested is not None for s in child.spans):
                    # spanless or only non-source spans: dummy location, unless child had suggestion spans (excluded)
                    if not child.spans:
                        secondary.append({"file":primary_file,"start":0,"end":0,"message":child.msg})
                walk(child.children)
        walk(diag.children)
        if diag.level=="error": typ,sev="Exception","error"
        elif diag.level=="warning": typ,sev="Warning","warning"
        else: typ,sev="Info","info"
        return {"sourceLocation":source_loc,"secondarySourceLocations":secondary,"type":typ,"component":"general","severity":sev,"errorCode":(str(diag.code) if diag.code else None),"message":diag.msg,"formattedMessage":self.renderer.render(diag)}

