# ============================= Sources & diagnostics =============================
import unicodedata, bisect

def char_width(ch):
    if ch=='\t': return 4
    o=ord(ch)
    if o<32 or o==127: return 1
    if unicodedata.combining(ch): return 0
    if unicodedata.category(ch) in ('Mn','Me','Cf'): return 0
    if unicodedata.east_asian_width(ch) in ('W','F'): return 2
    return 1

def disp_width(s):
    return sum(char_width(c) for c in s)

def display_text(s):
    # expand tabs to 4 spaces (annotate-snippets replaces tab with 4 spaces, not tab-stop)
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='\t': out.append('    ')
        elif o<32: out.append(chr(0x2400+o))
        elif o==127: out.append('␡')
        else: out.append(ch)
    return ''.join(out)

class SourceFile:
    __slots__=("fid","name","real_path","text","is_stdin","line_starts","byte_offs","is_yul")
    def __init__(self,fid,name,real_path,text,is_stdin=False,is_yul=False):
        self.fid=fid; self.name=name; self.real_path=real_path; self.text=text; self.is_stdin=is_stdin; self.is_yul=is_yul
        starts=[0]
        for i,ch in enumerate(text):
            if ch=='\n': starts.append(i+1)
        self.line_starts=starts
        bo=[0]*(len(text)+1); acc=0
        for i,ch in enumerate(text):
            acc+=len(ch.encode('utf-8')); bo[i+1]=acc
        self.byte_offs=bo
    def byte(self,pos):
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        return self.byte_offs[pos]
    def line_col(self,pos):
        if self.text=="":
            return (0,1)
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        idx=bisect.bisect_right(self.line_starts,pos)-1
        return (idx+1, pos-self.line_starts[idx]+1)
    def line_index(self,pos):
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        return bisect.bisect_right(self.line_starts,pos)-1
    def line_bounds(self,idx):
        start=self.line_starts[idx]
        end=self.line_starts[idx+1]-1 if idx+1<len(self.line_starts) else len(self.text)  # exclude \n, include \r
        return start,end
    def line_text(self,idx):
        s,e=self.line_bounds(idx); return self.text[s:e]
    def line_display(self,idx):
        raw=self.line_text(idx)
        # drop trailing \r if this line ended with \r\n
        if raw.endswith('\r') and idx+1<len(self.line_starts):
            raw=raw[:-1]
        return display_text(raw)

@dataclass
class SpanData:
    fid: int
    lo: int
    hi: int
    label: object=None
    is_primary: bool=True
    suggested: object=None
    is_suggestion: bool=False

@dataclass
class Diag:
    level: str
    msg: str
    code: object=None
    spans: list=field(default_factory=list)
    children: list=field(default_factory=list)
    created: object=None  # (created_loc, emitted_loc) for -Ztrack-diagnostics

def S(fid,lo,hi,label=None,primary=True):
    return SpanData(fid,lo,hi,label,primary)

LEVEL_COLOR={"error":"91","warning":"93","note":"92","help":"96"}
def _c(text,style,color):
    if not color or text=="": return text
    if style=="margin": return f"\x1b[1m\x1b[94m{text}\x1b[0m"
    if style=="bold": return f"\x1b[1m{text}\x1b[0m"
    if style.startswith("lvl:"):
        return f"\x1b[1m\x1b[{LEVEL_COLOR.get(style[4:],'91')}m{text}\x1b[0m"
    return text

@dataclass
class _Report:
    level:str; msg:str; code:object; spans:list; footers:list; main:bool=False

class DiagRenderer:
    def __init__(self,sources,style="unicode",color=False,width=None,ui_testing=False):
        self.sources=sources; self.style=style; self.color=color
        self.width=width if (width is not None and width>0) else 140
        # annotate enforces a minimum effective width; widths 0..small behave like ~? handled in margin
        self.ui_testing=ui_testing
    # ---------- report building ----------
    def build_reports(self,diag):
        main=_Report(diag.level,diag.msg,diag.code,list(diag.spans),[],True)
        reports=[main]
        def process(children):
            for child in children:
                if child.spans and any(s.suggested is not None for s in child.spans):
                    for s in child.spans:
                        if s.suggested is not None:
                            lab=f"{child.level}: {child.msg}: `{s.suggested}`"
                            main.spans.append(SpanData(s.fid,s.lo,s.hi,lab,False,s.suggested,True))
                    process(child.children)
                elif child.spans:
                    r=_Report(child.level,child.msg,child.code,list(child.spans),[],False)
                    reports.append(r); process(child.children)
                else:
                    reports[-1].footers.append((child.level,child.msg))
                    process(child.children)
        process(diag.children)
        return reports
    # ---------- margin ----------
    def margin_window(self,line_disp, spans_disp):
        """return (left,right) display-unit window into line_disp.
        spans_disp: list of (start,end) display offsets. Uses term width."""
        total=disp_width(line_disp)
        gutter=4  # refined below by caller via self._gutter
        gutter=getattr(self,"_gutter",4)
        budget=self.width - gutter
        if budget<10: budget=10 + (4-gutter if gutter<4 else 0)
        # Minimum observed: for very small widths content is 11 with gutter4 (budget 11?) emulate:
        if self.width<=10: budget=11-(gutter-4)
        if total<=budget:
            return (0,total)
        if not spans_disp:
            return (0,budget-1)
        sstart=min(s for s,e in spans_disp); send=max(e for s,e in spans_disp)
        left=0
        # threshold observed: if span_end + 10 > term width, shift
        if send + 10 > self.width or sstart> budget:
            ctx=self.width//2 - gutter
            if self.width<=10: ctx=4
            if ctx<4: ctx=4
            left=max(0,sstart-ctx)
        # right
        avail=budget-(1 if left>0 else 0)
        if total-left<=avail:
            right=total
        else:
            right=left+avail-1
        # ensure span end within window if possible (if span very long, keep start)
        return (left,right)
    def slice_display(self,text,left,right):
        """slice displayed text by display units; returns (sliced, start_char_index_map?) simple"""
        out=[]; col=0
        for ch in text:
            w=char_width(ch)
            if col>=left and col<right:
                out.append(ch)
            col+=w
            if col>=right and left==0:
                # continue scanning not needed but keep simple
                pass
        return ''.join(out)
    # ---------- rendering ----------
    def render(self,diag):
        if self.style=="short":
            return self.render_short(diag)
        reports=self.build_reports(diag)
        out=[]
        for ri,rep in enumerate(reports):
            is_last_report = (ri==len(reports)-1)
            out.append(self.title_line(rep))
            # group spans by file preserving order
            groups=[]; seen={}
            for s in rep.spans:
                if s.fid<0 or s.fid>=len(self.sources): continue
                if s.fid not in seen:
                    seen[s.fid]=len(groups); groups.append((s.fid,[]))
                groups[seen[s.fid]][1].append(s)
            if not groups:
                # snippet-less: footer structure like "  │\n  ╰ note: ..."
                if rep.footers:
                    w=2 if self.ui_testing else 1
                    out.extend(self.footer_lines(rep,w,has_snippet=False))
                elif not is_last_report and self.style=="unicode":
                    pass
                out.append("")  # blank separator handled below? We'll manage at end
                # remove the extra blank we just added; final join adds blank
                out.pop()
            else:
                for gi,(fid,fspans) in enumerate(groups):
                    is_last_group = is_last_report and gi==len(groups)-1
                    lines=self.render_snippet(fid,fspans,rep,footers=rep.footers if gi==len(groups)-1 else [],is_final=is_last_group)
                    out.extend(lines)
                    # unicode: if not final group/report and no footers tied, render_snippet appends ╰╴ line
            # Note: footers already rendered inside last snippet
        text="\n".join(out)
        if not text.endswith("\n"): text+="\n"
        text+="\n"
        return text
    def title_line(self,rep):
        lvl=rep.level + (f"[{rep.code}]" if rep.code else "")
        if self.color:
            if rep.main:
                return _c(lvl,f"lvl:{rep.level}",True)+_c(f": {rep.msg}","bold",True)
            else:
                return _c(lvl,f"lvl:{rep.level}",True)+f": {rep.msg}"
        return f"{lvl}: {rep.msg}"
    def footer_lines(self,rep,w,has_snippet=True):
        # returns lines starting with blank margin line then footers; unicode/ascii
        lines=[]
        uni=self.style=="unicode"
        marg="│" if uni else "|"
        pad=" "*(w+1)
        lines.append(pad+_c(marg,"margin",self.color))
        for idx,(lvl,msg) in enumerate(rep.footers):
            last=idx==len(rep.footers)-1
            if uni:
                corner="╰ " if last else "├ "
                first=pad+_c(corner,"margin",self.color)
            else:
                corner="= "
                first=pad+_c(corner,"margin",self.color)
            lvl_txt=_c(lvl,"bold",self.color)
            msg_lines=msg.split("\n")
            lines.append(first+lvl_txt+": "+msg_lines[0])
            # continuation lines aligned to after "╰ " (pad + 2) plus? Observed track diagnostics:
            # "  ╰ note: created at ...,\n          emitted at ..." -> 10 spaces = pad(2)+2+len("note: ")=10
            cont=" "*(w+1+2+len(lvl)+2)
            for ml in msg_lines[1:]:
                lines.append(cont+ml)
        return lines
    def render_short(self,diag):
        lvl=diag.level + (f"[{diag.code}]" if diag.code else "")
        span=None
        for s in diag.spans:
            if s.is_primary: span=s; break
        if span is None and diag.spans: span=diag.spans[0]
        prefix=""
        if span is not None and 0<=span.fid<len(self.sources):
            src=self.sources[span.fid]
            ln,col=src.line_col(span.lo)
            if ln>0:
                prefix=f"{src.name}:{ln}:{col}: "
        if self.color:
            return prefix+_c(lvl,f"lvl:{diag.level}",True)+f": {diag.msg}\n\n"
        return f"{prefix}{lvl}: {diag.msg}\n\n"
    def render_snippet(self,fid,fspans,rep,footers,is_final):
        src=self.sources[fid]
        uni=self.style=="unicode"
        # Empty source special: no snippet
        if src.text=="":
            return []
        # Determine line ranges.
        # Each span: start_line, end_line_exclusive-ish
        span_infos=[]
        for s in fspans:
            sl=src.line_index(s.lo)
            if s.hi>s.lo:
                el=src.line_index(s.hi-1)
            else:
                el=src.line_index(s.hi)
            span_infos.append((s,sl,el))
        # displayed lines
        displayed=[]
        def add_range(a,b):
            for x in range(a,b+1):
                if x not in displayed: displayed.append(x)
        folds=[]  # line index after which a fold occurs (display fold before next)
        for s,sl,el in span_infos:
            if el>sl:
                count=el-sl+1
                if count>7:
                    add_range(sl,sl+3); add_range(el-1,el)
                else:
                    add_range(sl,el)
            else:
                add_range(sl,sl)
        displayed.sort()
        max_line=max(displayed)+1 if displayed else 1
        w=2 if self.ui_testing else max(1,len(str(max_line)))
        self._gutter=w+3
        # primary span for origin
        prim=None
        for s in fspans:
            if s.is_primary: prim=s; break
        if prim is None: prim=fspans[0]
        ln,col=src.line_col(prim.lo)
        lines=[]
        pad=" "*(w+1)
        marg="│" if uni else "|"
        if uni:
            if self.color:
                origin=" "*w+_c(" ╭▸ ","margin",True)+f"{src.name}:{ln}:{col}"
            else:
                origin=pad+f"╭▸ {src.name}:{ln}:{col}"
        else:
            if self.color:
                origin=" "*w+_c("--> ","margin",True)+f"{src.name}:{ln}:{col}"
            else:
                origin=" "*w+f"--> {src.name}:{ln}:{col}"
        lines.append(origin)
        lines.append(pad+_c(marg,"margin",self.color))
        has_multi=any(el>sl for _,sl,el in span_infos)
        # For margin windows, compute per displayed line using spans on that line
        # Build per-line annotations (single-line spans and multi spans)
        prev_line=None
        for di,li in enumerate(displayed):
            if prev_line is not None and li>prev_line+1:
                # fold
                if uni:
                    bar="┃" if has_multi else ""
                    if self.color:
                        lines.append(pad+_c("‡","margin",True)+(" "+_c(bar,"margin",True) if bar else ""))
                    else:
                        lines.append(pad+"‡"+(" "+bar if bar else ""))
                else:
                    bar="|" if has_multi else ""
                    # ascii fold: "..." in line number area
                    lines.append("...  ".ljust(w+3)+bar if bar else "...")
            prev_line=li
            raw_disp=src.line_display(li)
            # spans relevant
            single=[s for s,sl,el in span_infos if sl==li and el==li]
            multi_here=[(s,sl,el) for s,sl,el in span_infos if el>sl and sl<=li<=el]
            # display offsets for single spans
            single_disp=[]
            line_start,_=src.line_bounds(li)
            # Note display offsets account control/tab expansion: compute by display_text prefix
            def doff(pos):
                seg=src.text[line_start:pos]
                return disp_width(display_text(seg[:-1] if seg.endswith('\r') and False else seg))
            for s in single:
                a=doff(s.lo); b=doff(s.hi)
                if b<=a: b=a+1
                single_disp.append((s,a,b))
            # for multi start/end offsets
            spans_for_margin=[(a,b) for _,a,b in single_disp]
            if multi_here:
                # margin based on full line
                pass
            left,right=self.margin_window(raw_disp,spans_for_margin)
            sliced=self.slice_display(raw_disp,left,right)
            if left>0: sliced_disp="…"+sliced
            else: sliced_disp=sliced
            if right<disp_width(raw_disp): sliced_disp=sliced_disp+"…"
            num="LL" if self.ui_testing else str(li+1)
            num_field=num.rjust(w)
            # multi annotation prefix
            prefix=""
            multi_start_row=False
            multi_start=None
            if has_multi:
                # determine if this line is first line of a multi span
                firsts=[(s,sl,el) for s,sl,el in multi_here if sl==li]
                if firsts:
                    s0=firsts[0][0]
                    # before span on line
                    before=src.text[line_start:s0.lo]
                    if before.strip()=="":
                        prefix=("┏ " if uni else "/ ")
                    else:
                        prefix="  "; multi_start_row=True; multi_start=s0
                elif multi_here:
                    prefix=("┃ " if uni else "| ")
                else:
                    prefix="  "
            if self.color:
                line_out=_c(num_field,"margin",True)+" "+_c(marg,"margin",True)+" "+( _c(prefix.rstrip(),"lvl:"+rep.level,True)+(" " if prefix else "") if prefix.strip() else prefix)+sliced_disp
                # Simplify: prefix colouring is approximate for multiline
                if not has_multi:
                    line_out=_c(num_field,"margin",True)+" "+_c(marg,"margin",True)+" "+sliced_disp
            else:
                line_out=f"{num_field} {marg} {prefix}{sliced_disp}"
            lines.append(line_out)
            # multi start row
            if multi_start_row and multi_start is not None:
                soff=doff(multi_start.lo)
                # window adjust
                adj=soff-left
                if uni:
                    content="┏"+"━"*(adj+1)+"┛"
                    if left>0:
                        # truncated start not expected often
                        content="┏"+"━"*(adj+1)+"┛"
                    lines.append(pad+_c(marg,"margin",self.color)+" "+(_c(content,f"lvl:{rep.level}",self.color)))
                else:
                    content=" "+"_"*(adj+1)+"^"
                    lines.append(pad+marg+" "+content)
            # single-line annotation rows
            if single_disp:
                is_last_line = (di==len(displayed)-1)
                # Sorting by start
                annots=sorted(single_disp,key=lambda x:(x[1],x[2]))
                rows=self._annotation_rows(annots,left,right,rep,is_final_snippet=is_final,has_footers=bool(footers),is_last_line=is_last_line,w=w)
                lines.extend(rows)
            # multi end row
            ends=[(s,sl,el) for s,sl,el in multi_here if el==li]
            if ends:
                s0=ends[0][0]
                eoff=doff(s0.hi)
                is_last_line=(di==len(displayed)-1)
                # label of multiline span?
                if uni:
                    cnt=max(1,eoff-left) if left==0 else max(1,eoff-left)
                    content="┗"+"━"*cnt+"┛"
                    if s0.label: content+=" "+s0.label
                    if is_last_line and is_final and not footers:
                        lines.append(pad+_c("╰╴","margin",self.color)+(_c(content,f"lvl:{rep.level}",self.color)))
                    else:
                        lines.append(pad+_c(marg,"margin",self.color)+" "+(_c(content,f"lvl:{rep.level}",self.color)))
                else:
                    cnt=max(1,eoff-left)
                    content="|"+"_"*cnt+"^"
                    if s0.label: content+=" "+s0.label
                    lines.append(pad+marg+" "+content)
        if footers:
            lines.extend(self.footer_lines(rep,w))
        elif not is_final:
            if uni:
                lines.append(pad+_c("╰╴","margin",self.color))
            else:
                lines.append(pad+_c(marg,"margin",self.color))
        return lines
    def _annotation_rows(self,annots,left,right,rep,is_final_snippet,has_footers,is_last_line,w):
        uni=self.style=="unicode"
        pad=" "*(w+1); marg="│" if uni else "|"
        # Determine deferred labeled spans (not last by start)
        labeled=[a for a in annots if a[0].label]
        last_start=max(a[1] for a in annots) if annots else 0
        deferred=[]; inline={}
        for s,a,b in annots:
            if s.label:
                if a<last_start:
                    deferred.append((s,a,b))
                else:
                    inline[id(s)]=s.label
        # build underline canvas
        # canvas map pos(display relative to left, plus 1 if left>0 for ellipsis) -> char/style-level
        shift=1 if left>0 else 0
        canvas={}
        maxpos=0
        deferred_starts={a for _,a,_ in deferred}
        for s,a,b in annots:
            for p in range(a-left+shift, max(a-left+shift+1,b-left+shift)):
                if s.is_primary:
                    ch="━" if uni else "^"
                else:
                    ch="─" if uni else "-"
                if uni and a in deferred_starts and p==a-left+shift and not s.is_primary:
                    ch="┬"
                canvas[p]=(ch,rep.level)
                maxpos=max(maxpos,p)
        def canvas_to_string(canvas,extra_label=None,extra_pos=None):
            if not canvas and extra_label is None: return ""
            maxp=max(canvas.keys()) if canvas else 0
            if extra_pos is not None: maxp=max(maxp,extra_pos+len(extra_label))
            chars=[]
            # color: underline chars groups by contiguous same style
            if not self.color:
                arr=[" "]*(maxp+1)
                for p,(ch,lv) in canvas.items(): arr[p]=ch
                out=''.join(arr).rstrip()
                if extra_label is not None:
                    if len(out)<extra_pos: out=out.ljust(extra_pos)
                    out+=extra_label
                return out
            else:
                # build segments
                out=""; i=0
                # simpler: iterate positions, group styled runs
                pos_sorted=sorted(canvas.keys())
                cur=0
                for p in pos_sorted:
                    if p>cur: out+=" "*(p-cur)
                    # contiguous run
                    run=""; q=p
                    # only include this char; grouping handled by sequential appends producing multiple escapes if not grouped
                    out+=_c(canvas[p][0],f"lvl:{rep.level}",True)
                    cur=p+1
                if extra_label is not None:
                    # cur is after last underline glyph
                    if extra_pos>cur: out+=" "*(extra_pos-cur)
                    out+=_c(extra_label.strip(),f"lvl:{rep.level}",True) if extra_label.startswith(" ") else extra_label
                    # annotate puts a plain space before label text
                    # Our extra_label handling in caller includes leading space handling separately
                return out
        inline_label=None; inline_pos=None
        for s,a,b in annots:
            if id(s) in inline:
                inline_pos=(b-left+shift)  # position after underline; label preceded by space
                inline_label=inline[id(s)]
        rows=[]
        final_row = is_last_line and is_final_snippet and not has_footers and not deferred
        if uni and final_row:
            margin_seg=_c("╰╴","margin",self.color)
            content=canvas_to_string(canvas)
            line=pad+margin_seg+content
            if inline_label is not None:
                # content string may contain ANSI; visual length of content without ansi
                # re-build with plain measurement
                if self.color:
                    # append space + coloured label after canvas string (canvas already ends at max glyph)
                    line=pad+margin_seg+content+" "+_c(inline_label,f"lvl:{rep.level}",True)
                else:
                    line=pad+margin_seg+content+" "+inline_label
            rows.append(line)
        else:
            content=canvas_to_string(canvas)
            line=pad+_c(marg,"margin",self.color)+content
            if inline_label is not None:
                if self.color:
                    line=pad+_c(marg,"margin",self.color)+content+" "+_c(inline_label,f"lvl:{rep.level}",True)
                else:
                    line=line+" "+inline_label
            rows.append(line)
        # deferred labels
        for di,(s,a,b) in enumerate(deferred):
            pos=a-left+shift
            # connector row
            conn=" "*pos+( "│" if uni else "|")
            rows.append(pad+_c(marg,"margin",self.color)+ ( _c(conn,f"lvl:{rep.level}",self.color) if False else conn))
            # label row
            lab=" "*pos+s.label
            is_last_deferred = di==len(deferred)-1
            if uni and is_last_line and is_final_snippet and not has_footers and is_last_deferred:
                rows.append(pad+_c("╰╴","margin",self.color)+lab)
            else:
                rows.append(pad+_c(marg,"margin",self.color)+lab)
        return rows

class Diagnostics:
    def __init__(self,sources,opts):
        self.sources=sources; self.opts=opts
        self.errors=0; self.warnings=0
        self.emitted=[]
        # color decision
        self.color_enabled=self._decide_color()
        self.renderer=DiagRenderer(sources,style=("short" if opts.error_format_human=="short" else opts.error_format_human),color=self.color_enabled,width=opts.diagnostic_width,ui_testing=opts.z.ui_testing)
    def _decide_color(self):
        if self.opts.color=="always": return True
        if self.opts.color=="never": return False
        # auto: anstream-like
        if os.environ.get("CLICOLOR_FORCE") not in (None,"","0"):
            # still NO_COLOR? supports-color precedence tested partially; NO_COLOR checked below first in original? Force may override. approximate:
            if os.environ.get("NO_COLOR"):
                pass
            else:
                return True
        if os.environ.get("NO_COLOR"): return False
        if os.environ.get("TERM")=="dumb": return False
        if os.environ.get("CLICOLOR")=="0": return False
        try: return sys.stderr.isatty()
        except Exception: return False
    def emit(self,diag):
        if diag.level=="error": self.errors+=1
        if diag.level=="warning":
            self.warnings+=1
            if self.opts.no_warnings: return
        # track diagnostics
        if self.opts.z.track_diagnostics and diag.created:
            created,emitted=diag.created
            diag.children.append(Diag("note",f"created at {created},\nemitted at {emitted}"))
        self.emitted.append(diag)
        # render & write to stderr immediately (important ordering vs stdout unflushed? Python stdout buffered separately; callers flush stdout before diagnostics in some phases)
        sys.stdout.flush()
        text=self.format_diag(diag)
        sys.stderr.write(text); sys.stderr.flush()
    def format_diag(self,diag):
        fmt=self.opts.error_format
        if fmt=="human":
            return self.renderer.render(diag)
        elif fmt=="rustc-json":
            obj=self.to_rustc_json(diag,top=True)
            if self.opts.pretty_json_err:
                return json.dumps(obj,indent=2,ensure_ascii=False)+"\n"
            return json.dumps(obj,separators=(",",":"),ensure_ascii=False)+"\n"
        elif fmt=="json":
            obj=self.to_solc_json(diag)
            if self.opts.pretty_json_err:
                return json.dumps(obj,indent=2,ensure_ascii=False)+"\n"
            return json.dumps(obj,separators=(",",":"),ensure_ascii=False)+"\n"
        return self.renderer.render(diag)
    def aborting(self):
        n=self.errors
        if n==1: msg="aborting due to 1 previous error"
        else: msg=f"aborting due to {n} previous errors"
        d=Diag("error",msg)
        # emit manually without counting
        sys.stdout.flush()
        sys.stderr.write(self.format_diag(d)); sys.stderr.flush()
    # ---- JSON conversions
    def span_rustc(self,s):
        src=self.sources[s.fid]
        ls,cs=src.line_col(s.lo)
        le,ce=src.line_col(s.hi)
        texts=[]
        if src.text!="":
            sl=src.line_index(s.lo); el=src.line_index(s.hi-1) if s.hi>s.lo else src.line_index(s.hi)
            # For spans ending at a newline, rustc includes two text entries (start line & end line col1)
            # Determine end line by line_col(hi): if hi is at line start and hi>lo, include that line too
            end_line_for_text=src.line_index(s.hi) if s.hi>len(src.text) else src.line_index(min(s.hi,len(src.text)))
            # rustc logic: iterate lines from ls-1 to le-1 based on line_col endpoints
            for li in range(ls-1, max(ls-1,le-1)+1):
                if li<0: continue
                # line_col line_end could be past last line if hi at EOF after newline
                if li>=len(src.line_starts): continue
                raw=src.line_text(li)
                lstart,_=src.line_bounds(li)
                hs=(s.lo-lstart+1) if li==ls-1 else 1
                he=(s.hi-lstart+1) if li==le-1 else (len(raw)+1)
                # For line before end if hi at start of next line, he on prev line is len+1
                texts.append({"text":raw,"highlight_start":hs,"highlight_end":he})
        return {"file_name":src.name,"byte_start":src.byte(s.lo),"byte_end":src.byte(s.hi),"line_start":ls,"line_end":le,"column_start":cs,"column_end":ce,"is_primary":s.is_primary,"text":texts,"label":s.label,"suggested_replacement":s.suggested}
    def to_rustc_json(self,diag,top=False):
        obj={}
        if top: obj["$message_type"]="diagnostic"
        obj["message"]=diag.msg
        obj["code"]=({"code":str(diag.code),"explanation":None} if diag.code else None)
        obj["level"]=diag.level
        obj["spans"]=[self.span_rustc(s) for s in diag.spans if 0<=s.fid<len(self.sources)]
        obj["children"]=[self.to_rustc_child(c) for c in diag.children]
        obj["rendered"]=self.renderer.render(diag) if top else None
        return obj
    def to_rustc_child(self,diag):
        return {"message":diag.msg,"code":({"code":str(diag.code),"explanation":None} if diag.code else None),"level":diag.level,"spans":[self.span_rustc(s) for s in diag.spans if 0<=s.fid<len(self.sources)],"children":[self.to_rustc_child(c) for c in diag.children],"rendered":None}
    def to_solc_json(self,diag):
        # primary span
        prim=None
        for s in diag.spans:
            if s.is_primary: prim=s; break
        if prim is None and diag.spans: prim=diag.spans[0]
        if prim is not None and 0<=prim.fid<len(self.sources):
            src=self.sources[prim.fid]
            source_loc={"file":src.name,"start":src.byte(prim.lo),"end":src.byte(prim.hi)}
            primary_file=src.name
        else:
            source_loc=None; primary_file=""
        secondary=[]
        def walk(children):
            for child in children:
                spanful=[s for s in child.spans if 0<=s.fid<len(self.sources) and s.suggested is None]
                if spanful:
                    for s in spanful:
                        src=self.sources[s.fid]
                        secondary.append({"file":src.name,"start":src.byte(s.lo),"end":src.byte(s.hi),"message":child.msg})
                elif not any(s.suggested is not None for s in child.spans):
                    # spanless or only non-source spans: dummy location, unless child had suggestion spans (excluded)
                    if not child.spans:
                        secondary.append({"file":primary_file,"start":0,"end":0,"message":child.msg})
                walk(child.children)
        walk(diag.children)
        if diag.level=="error": typ,sev="Exception","error"
        elif diag.level=="warning": typ,sev="Warning","warning"
        else: typ,sev="Info","info"
        return {"sourceLocation":source_loc,"secondarySourceLocations":secondary,"type":typ,"component":"general","severity":sev,"errorCode":(str(diag.code) if diag.code else None),"message":diag.msg,"formattedMessage":self.renderer.render(diag)}

