# ============================= Sources & diagnostics =============================
import unicodedata, bisect

def char_width(ch):
    if ch=='\t': return 4
    o=ord(ch)
    if o<32 or o==127: return 1
    if unicodedata.combining(ch): return 0
    if unicodedata.category(ch) in ('Mn','Me','Cf'): return 0
    if unicodedata.east_asian_width(ch) in ('W','F'): return 2
    return 1

def disp_width(s):
    return sum(char_width(c) for c in s)

def display_text(s):
    # expand tabs to 4 spaces (annotate-snippets replaces tab with 4 spaces, not tab-stop)
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='\t': out.append('    ')
        elif o<32: out.append(chr(0x2400+o))
        elif o==127: out.append('␡')
        else: out.append(ch)
    return ''.join(out)

class SourceFile:
    __slots__=("fid","name","real_path","text","is_stdin","line_starts","byte_offs","is_yul")
    def __init__(self,fid,name,real_path,text,is_stdin=False,is_yul=False):
        self.fid=fid; self.name=name; self.real_path=real_path; self.text=text; self.is_stdin=is_stdin; self.is_yul=is_yul
        starts=[0]
        for i,ch in enumerate(text):
            if ch=='\n': starts.append(i+1)
        self.line_starts=starts
        bo=[0]*(len(text)+1); acc=0
        for i,ch in enumerate(text):
            acc+=len(ch.encode('utf-8')); bo[i+1]=acc
        self.byte_offs=bo
    def byte(self,pos):
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        return self.byte_offs[pos]
    def line_col(self,pos):
        if self.text=="":
            return (0,1)
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        idx=bisect.bisect_right(self.line_starts,pos)-1
        return (idx+1, pos-self.line_starts[idx]+1)
    def line_index(self,pos):
        if pos<0: pos=0
        if pos>len(self.text): pos=len(self.text)
        return bisect.bisect_right(self.line_starts,pos)-1
    def line_bounds(self,idx):
        start=self.line_starts[idx]
        end=self.line_starts[idx+1]-1 if idx+1<len(self.line_starts) else len(self.text)  # exclude \n, include \r
        return start,end
    def line_text(self,idx):
        s,e=self.line_bounds(idx); return self.text[s:e]
    def line_display(self,idx):
        raw=self.line_text(idx)
        # drop trailing \r if this line ended with \r\n
        if raw.endswith('\r') and idx+1<len(self.line_starts):
            raw=raw[:-1]
        return display_text(raw)

@dataclass
class SpanData:
    fid: int
    lo: int
    hi: int
    label: object=None
    is_primary: bool=True
    suggested: object=None
    is_suggestion: bool=False

@dataclass
class Diag:
