LEVEL_COLOR={"error":"91","warning":"93","note":"92","help":"96"}
def _c(text,style,color):
    if not color or text=="": return text
    if style=="margin": return f"\x1b[1m\x1b[94m{text}\x1b[0m"
    if style=="bold": return f"\x1b[1m{text}\x1b[0m"
    if style.startswith("lvl:"):
        return f"\x1b[1m\x1b[{LEVEL_COLOR.get(style[4:],'91')}m{text}\x1b[0m"
    return text

@dataclass
class _Report:
    level:str; msg:str; code:object; spans:list; footers:list; main:bool=False

class DiagRenderer:
    def __init__(self,sources,style="unicode",color=False,width=None,ui_testing=False):
        self.sources=sources; self.style=style; self.color=color
        self.width=width if (width is not None and width>0) else 140
        # annotate enforces a minimum effective width; widths 0..small behave like ~? handled in margin
        self.ui_testing=ui_testing
    # ---------- report building ----------
    def build_reports(self,diag):
        main=_Report(diag.level,diag.msg,diag.code,list(diag.spans),[],True)
        reports=[main]
        def process(children):
            for child in children:
                if child.spans and any(s.suggested is not None for s in child.spans):
                    for s in child.spans:
                        if s.suggested is not None:
                            lab=f"{child.level}: {child.msg}: `{s.suggested}`"
                            main.spans.append(SpanData(s.fid,s.lo,s.hi,lab,False,s.suggested,True))
                    process(child.children)
                elif child.spans:
                    r=_Report(child.level,child.msg,child.code,list(child.spans),[],False)
                    reports.append(r); process(child.children)
                else:
                    reports[-1].footers.append((child.level,child.msg))
                    process(child.children)
        process(diag.children)
        return reports
    # ---------- margin ----------
    def margin_window(self,line_disp, spans_disp):
        """return (left,right) display-unit window into line_disp.
        spans_disp: list of (start,end) display offsets. Uses term width."""
        total=disp_width(line_disp)
        gutter=4  # refined below by caller via self._gutter
        gutter=getattr(self,"_gutter",4)
        budget=self.width - gutter
        if budget<10: budget=10 + (4-gutter if gutter<4 else 0)
        # Minimum observed: for very small widths content is 11 with gutter4 (budget 11?) emulate:
        if self.width<=10: budget=11-(gutter-4)
        if total<=budget:
            return (0,total)
        if not spans_disp:
            return (0,budget-1)
        sstart=min(s for s,e in spans_disp); send=max(e for s,e in spans_disp)
        left=0
        # threshold observed: if span_end + 10 > term width, shift
        if send + 10 > self.width or sstart> budget:
            ctx=self.width//2 - gutter
            if self.width<=10: ctx=4
            if ctx<4: ctx=4
            left=max(0,sstart-ctx)
        # right
        avail=budget-(1 if left>0 else 0)
        if total-left<=avail:
            right=total
        else:
            right=left+avail-1
        # ensure span end within window if possible (if span very long, keep start)
        return (left,right)
    def slice_display(self,text,left,right):
        """slice displayed text by display units; returns (sliced, start_char_index_map?) simple"""
        out=[]; col=0
        for ch in text:
            w=char_width(ch)
            if col>=left and col<right:
                out.append(ch)
            col+=w
            if col>=right and left==0:
                # continue scanning not needed but keep simple
                pass
        return ''.join(out)
    # ---------- rendering ----------
    def render(self,diag):
        if self.style=="short":
            return self.render_short(diag)
        reports=self.build_reports(diag)
        out=[]
        for ri,rep in enumerate(reports):
            is_last_report = (ri==len(reports)-1)
            out.append(self.title_line(rep))
            # group spans by file preserving order
            groups=[]; seen={}
            for s in rep.spans:
                if s.fid<0 or s.fid>=len(self.sources): continue
                if s.fid not in seen:
                    seen[s.fid]=len(groups); groups.append((s.fid,[]))
                groups[seen[s.fid]][1].append(s)
            if not groups:
                # snippet-less: footer structure like "  │\n  ╰ note: ..."
                if rep.footers:
                    w=2 if self.ui_testing else 1
                    out.extend(self.footer_lines(rep,w,has_snippet=False))
                elif not is_last_report and self.style=="unicode":
                    pass
                out.append("")  # blank separator handled below? We'll manage at end
                # remove the extra blank we just added; final join adds blank
                out.pop()
            else:
                for gi,(fid,fspans) in enumerate(groups):
                    is_last_group = is_last_report and gi==len(groups)-1
                    lines=self.render_snippet(fid,fspans,rep,footers=rep.footers if gi==len(groups)-1 else [],is_final=is_last_group)
                    out.extend(lines)
                    # unicode: if not final group/report and no footers tied, render_snippet appends ╰╴ line
            # Note: footers already rendered inside last snippet
        text="\n".join(out)
        if not text.endswith("\n"): text+="\n"
        text+="\n"
        return text
    def title_line(self,rep):
        lvl=rep.level + (f"[{rep.code}]" if rep.code else "")
        if self.color:
            if rep.main:
                return _c(lvl,f"lvl:{rep.level}",True)+_c(f": {rep.msg}","bold",True)
            else:
                return _c(lvl,f"lvl:{rep.level}",True)+f": {rep.msg}"
        return f"{lvl}: {rep.msg}"
    def footer_lines(self,rep,w,has_snippet=True):
        # returns lines starting with blank margin line then footers; unicode/ascii
        lines=[]
        uni=self.style=="unicode"
        marg="│" if uni else "|"
        pad=" "*(w+1)
        lines.append(pad+_c(marg,"margin",self.color))
        for idx,(lvl,msg) in enumerate(rep.footers):
            last=idx==len(rep.footers)-1
            if uni:
                corner="╰ " if last else "├ "
                first=pad+_c(corner,"margin",self.color)
            else:
                corner="= "
                first=pad+_c(corner,"margin",self.color)
            lvl_txt=_c(lvl,"bold",self.color)
            msg_lines=msg.split("\n")
            lines.append(first+lvl_txt+": "+msg_lines[0])
            # continuation lines aligned to after "╰ " (pad + 2) plus? Observed track diagnostics:
            # "  ╰ note: created at ...,\n          emitted at ..." -> 10 spaces = pad(2)+2+len("note: ")=10
            cont=" "*(w+1+2+len(lvl)+2)
            for ml in msg_lines[1:]:
                lines.append(cont+ml)
