    def render_short(self,diag):
        lvl=diag.level + (f"[{diag.code}]" if diag.code else "")
        span=None
        for s in diag.spans:
            if s.is_primary: span=s; break
        if span is None and diag.spans: span=diag.spans[0]
        prefix=""
        if span is not None and 0<=span.fid<len(self.sources):
            src=self.sources[span.fid]
            ln,col=src.line_col(span.lo)
            if ln>0:
                prefix=f"{src.name}:{ln}:{col}: "
        if self.color:
            return prefix+_c(lvl,f"lvl:{diag.level}",True)+f": {diag.msg}\n\n"
        return f"{prefix}{lvl}: {diag.msg}\n\n"
    def render_snippet(self,fid,fspans,rep,footers,is_final):
        src=self.sources[fid]
        uni=self.style=="unicode"
        # Empty source special: no snippet
        if src.text=="":
            return []
        # Determine line ranges.
        # Each span: start_line, end_line_exclusive-ish
        span_infos=[]
        for s in fspans:
            sl=src.line_index(s.lo)
            if s.hi>s.lo:
                el=src.line_index(s.hi-1)
            else:
                el=src.line_index(s.hi)
            span_infos.append((s,sl,el))
        # displayed lines
