                arr=[" "]*(maxp+1)
                for p,(ch,lv) in canvas.items(): arr[p]=ch
                out=''.join(arr).rstrip()
                if extra_label is not None:
                    if len(out)<extra_pos: out=out.ljust(extra_pos)
                    out+=extra_label
                return out
            else:
