# ============================= Parser =============================
class ParseError(Exception):
    def __init__(self,diag): self.diag=diag

def fmt_expected(items):
    if len(items)==1: return items[0]
    if len(items)==2: return f"{items[0]} or {items[1]}"
    return ", ".join(items[:-1])+", or "+items[-1]

class Parser:
    def __init__(self,toks,src,dcx):
        self.toks=toks; self.src=src; self.fid=src.fid; self.dcx=dcx; self.pos=0
        self.imports=[]  # AST import items collected in order (Item nodes)
    # token helpers
    def cur(self): return self.toks[self.pos]
    def prev(self): return self.toks[self.pos-1] if self.pos>0 else self.toks[0]
    def peek(self,k=0):
        return self.toks[min(self.pos+k,len(self.toks)-1)]
    def at_eof(self): return self.cur().kind=="eof"
    def bump(self):
        t=self.cur();
        if t.kind!="eof": self.pos+=1
        return t
    def check(self,kind): return self.cur().kind==kind
    def check_text(self,txt): return self.cur().kind=="ident" and self.cur().text==txt
    def eat(self,kind):
        if self.check(kind): return self.bump()
        return None
    def eat_text(self,txt):
        if self.check_text(txt): return self.bump()
        return None
    def err_span(self,tok=None):
        tok=tok or self.cur()
        if tok.kind=="eof":
            if self.pos>0: p=self.prev(); return span_of(p)
            return (self.fid,0,0)
        return span_of(tok)
    def error(self,msg,span=None,children=None,code=None,label=None):
        span=span or self.err_span()
        d=Diag("error",msg,code=code,spans=[sd(span,label)],children=children or [])
        raise ParseError(d)
    def dcx_error(self,msg,span,children=None,code=None):
        return _diag(self.dcx,msg,span,children=children,code=code)
    def expected(self,items,tok=None):
        tok=tok or self.cur()
        found=tok.describe()
        if len(items)==1:
            msg=f"expected {items[0]}, found {found}"; label=f"expected {items[0]}"
            # identifier / special categories have no label in original
            if items[0] in ("identifier","string literal"): label=None
        else:
            msg=f"expected one of {fmt_expected(items)}, found {found}"
            if len(items)>6: label=f"expected one of {len(items)} possible tokens"
            else: label=f"expected one of {fmt_expected(items)}"
        self.error(msg,span=self.err_span(tok),label=label)
    def expect(self,kind,disp=None):
        if self.check(kind): return self.bump()
        self.expected([disp or f"`{kind}`"])
    def expect_text(self,txt):
        if self.check_text(txt): return self.bump()
        self.expected([f"`{txt}`"])
    def is_ident_tok(self,tok):
        return tok.kind=="ident" and tok.cat in ("ident","yulkw","yulbuiltin")
    def parse_ident(self):
        t=self.cur()
        if self.is_ident_tok(t):
            self.bump(); return Id(t.text,span_of(t))
        # expected identifier (no label)
        self.error(f"expected identifier, found {t.describe()}",span=self.err_span())
    def parse_any_ident_for_member(self):
        t=self.cur()
        if self.is_ident_tok(t) or (t.kind=="ident" and t.text=="address"):
            self.bump(); return Id(t.text,span_of(t))
        self.error(f"expected identifier, found {t.describe()}",span=self.err_span())
    def eat_ident(self):
        if self.is_ident_tok(self.cur()):
            t=self.bump(); return Id(t.text,span_of(t))
        return None
    def parse_path(self):
        first=self.parse_ident(); parts=[first]
        while self.check("."):
            self.bump(); parts.append(self.parse_ident())
        return parts
    # ---------- docs ----------
    def make_docs(self,tok_docs):
        docs=[]
        for kind,lo,hi,content in tok_docs or []:
            docs.append(make_doc_comment(self.src,kind,lo,hi,content))
        return docs
    # ---------- literals ----------
    def parse_string_lit_from_tok(self,tok):
        res=parse_string_content(tok,self.dcx)
        return res
    # ---------- Types ----------
    def is_type_start(self,tok=None):
        tok=tok or self.cur()
        if tok.kind!="ident": return False
        if tok.text in ("mapping","function"): return True
        if _is_elem_type_word(tok.text): return True
        if self.is_ident_tok(tok): return True
        return False
    def parse_type(self):
        t=self.cur(); start=t
        ty=None
        if t.kind=="ident" and t.text=="mapping":
            self.bump(); self.expect("(")
            key=self.parse_type()
            key_name=self.eat_ident()
            self.expect("=>")
            value=self.parse_type()
            value_name=self.eat_ident()
            close=self.expect(")")
            ty=Node("Type",(self.fid,start.lo,close.hi),tkind=("mapping",key,key_name,value,value_name))
        elif t.kind=="ident" and t.text=="function":
            self.bump()
            params=self.parse_parameter_list()
            # function type attributes
            vis=None; mut=None; returns=None
            while True:
                if self.cur().kind=="ident" and self.cur().text in ("external","internal"):
                    vt=self.bump(); vis=(vt.text.capitalize(),span_of(vt)); continue
                if self.cur().kind=="ident" and self.cur().text in ("pure","view","payable"):
                    mt=self.bump(); mut=(mt.text,span_of(mt)); continue
                if self.check_text("returns"):
                    self.bump(); returns=self.parse_parameter_list(); continue
                break
            end=returns.span if returns else (params.span if not (vis or mut) else (self.prev().hi and (self.fid,start.lo,self.prev().hi)))
            span=(self.fid,start.lo, self.prev().hi if self.prev()!=start else start.hi)
            ty=Node("Type",span,tkind=("function",params,vis,mut,returns))
        elif t.kind=="ident" and _is_elem_type_word(t.text):
            self.bump(); end=t.hi; ekind=elem_kind_of(t.text)
            if t.text=="address" and self.check_text("payable"):
                pt=self.bump(); end=pt.hi; ekind=("address_payable",)
            ty=Node("Type",(self.fid,start.lo,end),tkind=("elem",ekind))
        elif self.is_ident_tok(t):
            parts=self.parse_path()
            ty=Node("Type",span_join(parts[0].span,parts[-1].span),tkind=("custom",parts))
        else:
            self.expected(["`function`","`mapping`","elementary type name","path"])
        # array suffixes
        while self.check("["):
            self.bump(); size=None
            if not self.check("]"):
                size=self.parse_expr()
            close=self.expect("]")
            ty=Node("Type",(self.fid,ty.span[1],close.hi),tkind=("array",ty,size))
        return ty
    # ---------- variable definitions / parameters ----------
    def parse_parameter_list(self):
        open_tok=self.expect("(")
        vars=[]
