def elem_kind_of(word):
    if word=="address": return ("address",)
    if word=="bool": return ("bool",)
    if word=="string": return ("string",)
    if word=="bytes": return ("bytes",)
    if word=="fixed": return ("fixed",0,0)
    if word=="ufixed": return ("ufixed",0,0)
    m=re.fullmatch(r'(u?int)(\d*)',word)
    if m: return ("uint" if m.group(1)=="uint" else "int", int(m.group(2)) if m.group(2) else 0)
    m=re.fullmatch(r'bytes(\d+)',word)
    if m: return ("fixedbytes",int(m.group(1)))
    return ("bytes",)

def make_doc_comment(src,kind,lo,hi,content):
    # Parse NatSpec items inside content (for AST dump)
