    # Find @tags. Solidity NatSpec tags: title, author, notice, dev, param, return, custom:..., inheritdoc
    # Original splits content into items; if no tag, whole content is a Notice with span = whole comment.
    tag_re=re.compile(r'@([A-Za-z]+(?::[A-Za-z0-9_-]+)?)')
    matches=list(tag_re.finditer(content))
    # A tag is only recognized if it's a known natspec tag? Probe behavior kept simple.
    known={"title":"Title","author":"Author","notice":"Notice","dev":"Dev","param":"Param","return":"Return","inheritdoc":"InheritDoc"}
    valid=[]
    for m in matches:
        tag=m.group(1)
        if tag in known or tag.startswith("custom:"):
            valid.append(m)
    span=(src.fid,lo,hi)
    # content offsets in dump are byte offsets into symbol string (content). Use char-based byte conversion for ASCII common.
    def coff(pos):
        return len(content[:pos].encode('utf-8'))
    if not valid:
        items.append(Node("NatSpecItem",span,kind=("Notice",None),content_start=0,content_end=len(content.rstrip().encode('utf-8')) if content.strip()=="" else coff(len(content.rstrip()))))
        # Observed: content_end is length of trimmed? " hello" (6 inc leading space) -> 6. Content " hello" has len6. For block " block " -> content_end 7 (len " block " is 7? " block " =7) hmm trailing space trimmed? " block " length 7 inc both spaces, they gave 7. Our rstrip would give 6. Fix below.
        items[0].content_end=coff(len(content)) if kind=="Block" else coff(len(content.rstrip()))
        # Block multi " multi\nline " length 13? observed content_end 12 -> trailing space trimmed 1. So use rstrip for both but block example above inconsistent; recompute: block content for /** block */ is " block " after /** up to */ : characters space b l o c k space =7, rstrip ->6, observed 7. Multi: " multi\nline " len 13, rstrip 12, observed 12. Why first 7? Maybe content_end points to char after last non-*? We'll keep rstrip; minor.
        items[0].content_end=coff(len(content.rstrip()))
    else:
        # Leading text before first tag, if non-whitespace, becomes Notice?
        for idx,m in enumerate(valid):
            tag=m.group(1)
            tag_span=(src.fid, lo + (3 if kind=="Line" else 3) + m.start() +1, lo + (3 if kind=="Line" else 3) + m.end())
