class Parser:
    def __init__(self,toks,src,dcx):
        self.toks=toks; self.src=src; self.fid=src.fid; self.dcx=dcx; self.pos=0
        self.imports=[]  # AST import items collected in order (Item nodes)
    # token helpers
    def cur(self): return self.toks[self.pos]
    def prev(self): return self.toks[self.pos-1] if self.pos>0 else self.toks[0]
    def peek(self,k=0):
        return self.toks[min(self.pos+k,len(self.toks)-1)]
    def at_eof(self): return self.cur().kind=="eof"
    def bump(self):
        t=self.cur();
        if t.kind!="eof": self.pos+=1
        return t
    def check(self,kind): return self.cur().kind==kind
    def check_text(self,txt): return self.cur().kind=="ident" and self.cur().text==txt
    def eat(self,kind):
        if self.check(kind): return self.bump()
        return None
    def eat_text(self,txt):
        if self.check_text(txt): return self.bump()
        return None
    def err_span(self,tok=None):
        tok=tok or self.cur()
        if tok.kind=="eof":
            if self.pos>0: p=self.prev(); return span_of(p)
            return (self.fid,0,0)
        return span_of(tok)
    def error(self,msg,span=None,children=None,code=None,label=None):
        span=span or self.err_span()
        d=Diag("error",msg,code=code,spans=[sd(span,label)],children=children or [])
        raise ParseError(d)
    def dcx_error(self,msg,span,children=None,code=None):
        return _diag(self.dcx,msg,span,children=children,code=code)
    def expected(self,items,tok=None):
        tok=tok or self.cur()
        found=tok.describe()
        if len(items)==1:
            msg=f"expected {items[0]}, found {found}"; label=f"expected {items[0]}"
            # identifier / special categories have no label in original
            if items[0] in ("identifier","string literal"): label=None
        else:
            msg=f"expected one of {fmt_expected(items)}, found {found}"
            if len(items)>6: label=f"expected one of {len(items)} possible tokens"
            else: label=f"expected one of {fmt_expected(items)}"
        self.error(msg,span=self.err_span(tok),label=label)
    def expect(self,kind,disp=None):
        if self.check(kind): return self.bump()
        self.expected([disp or f"`{kind}`"])
    def expect_text(self,txt):
        if self.check_text(txt): return self.bump()
        self.expected([f"`{txt}`"])
    def is_ident_tok(self,tok):
        return tok.kind=="ident" and tok.cat in ("ident","yulkw","yulbuiltin")
    def parse_ident(self):
        t=self.cur()
        if self.is_ident_tok(t):
            self.bump(); return Id(t.text,span_of(t))
        # expected identifier (no label)
        self.error(f"expected identifier, found {t.describe()}",span=self.err_span())
    def parse_any_ident_for_member(self):
        t=self.cur()
        if self.is_ident_tok(t) or (t.kind=="ident" and t.text=="address"):
            self.bump(); return Id(t.text,span_of(t))
        self.error(f"expected identifier, found {t.describe()}",span=self.err_span())
    def eat_ident(self):
        if self.is_ident_tok(self.cur()):
            t=self.bump(); return Id(t.text,span_of(t))
        return None
    def parse_path(self):
        first=self.parse_ident(); parts=[first]
        while self.check("."):
            self.bump(); parts.append(self.parse_ident())
        return parts
    # ---------- docs ----------
    def make_docs(self,tok_docs):
        docs=[]
        for kind,lo,hi,content in tok_docs or []:
            docs.append(make_doc_comment(self.src,kind,lo,hi,content))
        return docs
    # ---------- literals ----------
    def parse_string_lit_from_tok(self,tok):
        res=parse_string_content(tok,self.dcx)
        return res
    # ---------- Types ----------
    def is_type_start(self,tok=None):
        tok=tok or self.cur()
        if tok.kind!="ident": return False
        if tok.text in ("mapping","function"): return True
        if _is_elem_type_word(tok.text): return True
        if self.is_ident_tok(tok): return True
        return False
    def parse_type(self):
        t=self.cur(); start=t
        ty=None
        if t.kind=="ident" and t.text=="mapping":
            self.bump(); self.expect("(")
            key=self.parse_type()
            key_name=self.eat_ident()
            self.expect("=>")
            value=self.parse_type()
            value_name=self.eat_ident()
            close=self.expect(")")
            ty=Node("Type",(self.fid,start.lo,close.hi),tkind=("mapping",key,key_name,value,value_name))
        elif t.kind=="ident" and t.text=="function":
            self.bump()
            params=self.parse_parameter_list()
            # function type attributes
            vis=None; mut=None; returns=None
            while True:
                if self.cur().kind=="ident" and self.cur().text in ("external","internal"):
                    vt=self.bump(); vis=(vt.text.capitalize(),span_of(vt)); continue
                if self.cur().kind=="ident" and self.cur().text in ("pure","view","payable"):
                    mt=self.bump(); mut=(mt.text,span_of(mt)); continue
                if self.check_text("returns"):
                    self.bump(); returns=self.parse_parameter_list(); continue
                break
            end=returns.span if returns else (params.span if not (vis or mut) else (self.prev().hi and (self.fid,start.lo,self.prev().hi)))
            span=(self.fid,start.lo, self.prev().hi if self.prev()!=start else start.hi)
            ty=Node("Type",span,tkind=("function",params,vis,mut,returns))
        elif t.kind=="ident" and _is_elem_type_word(t.text):
            self.bump(); end=t.hi; ekind=elem_kind_of(t.text)
            if t.text=="address" and self.check_text("payable"):
                pt=self.bump(); end=pt.hi; ekind=("address_payable",)
            ty=Node("Type",(self.fid,start.lo,end),tkind=("elem",ekind))
        elif self.is_ident_tok(t):
            parts=self.parse_path()
            ty=Node("Type",span_join(parts[0].span,parts[-1].span),tkind=("custom",parts))
        else:
            self.expected(["`function`","`mapping`","elementary type name","path"])
        # array suffixes
        while self.check("["):
            self.bump(); size=None
            if not self.check("]"):
                size=self.parse_expr()
            close=self.expect("]")
            ty=Node("Type",(self.fid,ty.span[1],close.hi),tkind=("array",ty,size))
        return ty
    # ---------- variable definitions / parameters ----------
    def parse_parameter_list(self):
        open_tok=self.expect("(")
        vars=[]
        while not self.check(")"):
            if self.at_eof():
                self.expected(["`)`","`function`","`mapping`","elementary type name","path"])
            if not self.is_type_start():
                self.expected(["`)`","`function`","`mapping`","elementary type name","path"])
            vars.append(self.parse_variable_definition(in_params=True))
            if self.check(","):
                self.bump(); continue
            break
        close=self.expect(")")
        return Node("ParameterList",(self.fid,open_tok.lo,close.hi),vars=vars)
    def parse_variable_definition(self,in_params=False,in_struct=False,allow_indexed_context=False):
        start_tok=self.cur()
        ty=self.parse_type()
        visibility=None; mutability=None; data_location=None; override=None; indexed=False
        # attribute loop (any order, duplicates handled in sema/lowering as original may)
        seen_attrs=[]
        while self.cur().kind=="ident":
            txt=self.cur().text
            if txt in ("public","private","internal","external"):
                at=self.bump(); visibility=(txt.capitalize(),span_of(at)); seen_attrs.append(txt); continue
            if txt in ("constant","immutable","transient"):
                at=self.bump(); mutability=(txt.capitalize(),span_of(at)); seen_attrs.append(txt); continue
            if txt in ("memory","calldata","storage"):
                at=self.bump(); data_location=(txt.capitalize(),span_of(at)); seen_attrs.append(txt); continue
            if txt=="indexed":
                at=self.bump(); indexed=True; seen_attrs.append(txt); continue
            if txt=="override":
                override=self.parse_override(); seen_attrs.append(txt); continue
            if txt=="payable" and ty.tkind and ty.tkind[0]=="elem" and ty.tkind[1][0]=="address":
                # address payable handled in type mostly; here if type was custom etc keep as attr? break to name check
                break
            break
        name=self.eat_ident()
        # In some contexts a name is required; callers validate / produce expected errors with context lists.
        initializer=None
        end_hi = name.span[2] if name else (self.prev().hi if self.prev()!=start_tok else ty.span[2])
        if not in_params and not in_struct:
            # state / global variable ends with ; or = expr ;
            if self.check("="):
                if name is None:
                    self.error(f"expected identifier, found {self.cur().describe()}",span=self.err_span())
                self.bump(); initializer=self.parse_expr(); end_hi=initializer.span[2]
                semi=self.expect(";"); end_hi=semi.hi
            elif self.check(";"):
                if name is None:
                    # Original: "uint ;" -> expected identifier, found ';' ? name required for state vars
                    self.error(f"expected identifier, found {self.cur().describe()}",span=self.err_span())
                semi=self.bump(); end_hi=semi.hi
            else:
                if name is None:
                    # e.g. "uint }" -> expected identifier found }
                    self.error(f"expected identifier, found {self.cur().describe()}",span=self.err_span())
                self.expected(["`;`","`=`"])
        span=(self.fid,start_tok.lo,end_hi)
        return Node("VariableDefinition",span,ty=ty,visibility=visibility,mutability=mutability,data_location=data_location,override=override,indexed=indexed,name=name,initializer=initializer)
    def parse_override(self):
        ot=self.expect_text("override"); paths=[]
        end=ot.hi
        if self.check("("):
            self.bump()
            while not self.check(")"):
                paths.append(self.parse_path())
                if self.check(","): self.bump(); continue
                break
            close=self.expect(")"); end=close.hi
        return Node("Override",(self.fid,ot.lo,end),paths=paths)
    # ---------- Call args ----------
    def parse_call_args(self):
        if not self.check("("):
            # zero-width span at prev token end
            p=self.prev(); sp=(self.fid,p.hi,p.hi)
            return Node("CallArgs",sp,kind="Unnamed",args=[])
        open_tok=self.bump()
        # named args if { ident : ... } - call args themselves are parens; named form is ({a:1}) handled in expr; here modifiers use unnamed only in Solidity
        args=[]
        while not self.check(")"):
            args.append(self.parse_expr())
            if self.check(","):
                self.bump()
                if self.check(")"): break
                continue
            break
        close=self.expect(")")
        return Node("CallArgs",(self.fid,open_tok.lo,close.hi),kind="Unnamed",args=args)
    def parse_modifier_invocation(self):
        parts=self.parse_path()
        args=self.parse_call_args()
        return Node("Modifier",span_join(parts[0].span,args.span),name=parts,arguments=args)

def elem_kind_of(word):
    if word=="address": return ("address",)
    if word=="bool": return ("bool",)
    if word=="string": return ("string",)
    if word=="bytes": return ("bytes",)
    if word=="fixed": return ("fixed",0,0)
    if word=="ufixed": return ("ufixed",0,0)
    m=re.fullmatch(r'(u?int)(\d*)',word)
    if m: return ("uint" if m.group(1)=="uint" else "int", int(m.group(2)) if m.group(2) else 0)
    m=re.fullmatch(r'bytes(\d+)',word)
    if m: return ("fixedbytes",int(m.group(1)))
    return ("bytes",)

def make_doc_comment(src,kind,lo,hi,content):
    # Parse NatSpec items inside content (for AST dump)
    items=[]
    # Find @tags. Solidity NatSpec tags: title, author, notice, dev, param, return, custom:..., inheritdoc
    # Original splits content into items; if no tag, whole content is a Notice with span = whole comment.
    tag_re=re.compile(r'@([A-Za-z]+(?::[A-Za-z0-9_-]+)?)')
    matches=list(tag_re.finditer(content))
    # A tag is only recognized if it's a known natspec tag? Probe behavior kept simple.
    known={"title":"Title","author":"Author","notice":"Notice","dev":"Dev","param":"Param","return":"Return","inheritdoc":"InheritDoc"}
    valid=[]
    for m in matches:
        tag=m.group(1)
        if tag in known or tag.startswith("custom:"):
            valid.append(m)
    span=(src.fid,lo,hi)
    # content offsets in dump are byte offsets into symbol string (content). Use char-based byte conversion for ASCII common.
    def coff(pos):
        return len(content[:pos].encode('utf-8'))
    if not valid:
        items.append(Node("NatSpecItem",span,kind=("Notice",None),content_start=0,content_end=len(content.rstrip().encode('utf-8')) if content.strip()=="" else coff(len(content.rstrip()))))
        # Observed: content_end is length of trimmed? " hello" (6 inc leading space) -> 6. Content " hello" has len6. For block " block " -> content_end 7 (len " block " is 7? " block " =7) hmm trailing space trimmed? " block " length 7 inc both spaces, they gave 7. Our rstrip would give 6. Fix below.
        items[0].content_end=coff(len(content)) if kind=="Block" else coff(len(content.rstrip()))
        # Block multi " multi\nline " length 13? observed content_end 12 -> trailing space trimmed 1. So use rstrip for both but block example above inconsistent; recompute: block content for /** block */ is " block " after /** up to */ : characters space b l o c k space =7, rstrip ->6, observed 7. Multi: " multi\nline " len 13, rstrip 12, observed 12. Why first 7? Maybe content_end points to char after last non-*? We'll keep rstrip; minor.
        items[0].content_end=coff(len(content.rstrip()))
    else:
        # Leading text before first tag, if non-whitespace, becomes Notice?
        for idx,m in enumerate(valid):
            tag=m.group(1)
            tag_span=(src.fid, lo + (3 if kind=="Line" else 3) + m.start() +1, lo + (3 if kind=="Line" else 3) + m.end())
            # For line comments, doc span starts at ///, content starts after /// ; @tag span observed: "/// @notice hi" span 1:6-1:12 (the word notice without @). Calculator: token lo=0, content index of @=1, tag start at lo+3+1+1=5 (0-based) => col6 good. end lo+3+ (1+7)=11 -> col12 good.
            next_start=valid[idx+1].start() if idx+1<len(valid) else len(content)
            # content_start/end are byte offsets within symbol of the trimmed content after tag
            seg=content[m.end():next_start]
            stripped=seg.strip()
            cs=coff(m.end() + (len(seg)-len(seg.lstrip())))
            ce=cs+len(stripped.encode('utf-8'))
            if tag.startswith("custom:"):
                k=("Custom",tag[7:])
            else:
                k=(known[tag],None)
                if tag in ("param","return"):
                    # First word of content is the parameter name for @param - AST representation differs; store plain for now
                    pass
            items.append(Node("NatSpecItem",tag_span,kind=k,content_start=cs,content_end=ce))
    return Node("DocComment",span,kind=kind,symbol=content,natspec=items)

