# ============================= File loading / driver =============================
def normalize_virtual(path):
    parts=[]
    for comp in path.split("/"):
        if comp in ("","."): continue
        if comp=="..":
            if parts: parts.pop()
            continue
        parts.append(comp)
    return "/".join(parts)

def absolutize_lexical(path,cwd):
    if not os.path.isabs(path):
        path=os.path.join(cwd,path)
    # lexical normalization
    parts=[]
    for comp in path.split("/"):
        if comp in ("","."): continue
        if comp=="..":
            if parts: parts.pop()
            continue
        parts.append(comp)
    return "/"+"/".join(parts)

