# ============================= Rust Debug pretty printing =============================
def dbg_raw(text): return ("raw",text)
def dbg_struct(name,fields): return ("struct",name,fields)
def dbg_tuple(name,args): return ("tuple",name,args)
def dbg_list(items): return ("list",items)
def dbg_named_list(name,items): return ("nlist",name,items)
def dbg_opt(v): return ("opt",v)
def dbg_span(span,srcs): return ("span",span,srcs)
def dbg_tuple_plain(args): return ("ptuple",args)

def format_dbg(node,indent=0):
    kind=node[0]
    pad="    "*indent; pad1="    "*(indent+1)
    if kind=="raw": return node[1]
    if kind=="span":
        span=node[1]; srcs=node[2]
        if span is None: return "no-location"
        fid,lo,hi=span
        if lo<0: return "no-location"
        src=srcs[fid]; l1,c1=src.line_col(lo); l2,c2=src.line_col(hi)
        return f"{src.name}:{l1}:{c1}: {l2}:{c2}"
    if kind=="opt":
        if node[1] is None: return "None"
        return "Some(\n"+pad1+format_dbg(node[1],indent+1)+",\n"+pad+")"
    if kind=="struct":
        name,fields=node[1],node[2]
        if not fields: return name
        out=[name+" {"]
        for fname,val in fields:
            out.append(pad1+f"{fname}: "+format_dbg(val,indent+1)+",")
        out.append(pad+"}")
        return "\n".join(out)
    if kind=="tuple":
        name,args=node[1],node[2]
        if not args: return name
        out=[name+"("]
        for a in args: out.append(pad1+format_dbg(a,indent+1)+",")
        out.append(pad+")")
        return "\n".join(out)
    if kind=="ptuple":
        args=node[1]
        out=["("]
        for a in args: out.append(pad1+format_dbg(a,indent+1)+",")
        out.append(pad+")")
        return "\n".join(out)
    if kind=="list":
        items=node[1]
        if not items: return "[]"
        out=["["]
        for a in items: out.append(pad1+format_dbg(a,indent+1)+",")
        out.append(pad+"]")
        return "\n".join(out)
    if kind=="nlist":
        name,items=node[1],node[2]
        if not items: return name+"[]"
        out=[name+"["]
        for a in items: out.append(pad1+format_dbg(a,indent+1)+",")
        out.append(pad+"]")
        return "\n".join(out)
    raise AssertionError(node)

def dbg_id(id_):
    return dbg_raw(id_.name if id_ else "")
def dbg_opt_id(id_):
    return dbg_opt(dbg_id(id_) if id_ is not None else None)
def dbg_str(s):
    return dbg_raw(rust_debug_str(s))

