# ============================= AST dump conversion =============================
class AstDbg:
    def __init__(self,compiler): self.c=compiler; self.srcs=compiler.sources
    def sp(self,span): return dbg_span(span,self.srcs)
    def sources(self):
        return dbg_named_list("ParsedSources",[self.source(s) for s in self.c.sources])
    def source(self,s):
        if s.is_stdin: file_node=dbg_raw("Stdin")
        else: file_node=dbg_tuple("Real",[dbg_str(s.real_path)])
        imports=dbg_list([dbg_tuple_plain([dbg_raw(f"ItemId({idx})"),dbg_raw(f"SourceId({fid})")]) for idx,fid in s.import_list])
        if s.ast is None: ast=dbg_raw("None")
        else: ast=dbg_opt(dbg_named_list("SourceUnit",[self.item(x) for x in s.ast]))
        return dbg_struct("Source",[("file",file_node),("imports",imports),("ast",ast)])
    def docs(self,docs):
        return dbg_named_list("DocComments",[self.doc(d) for d in docs])
    def doc(self,d):
        items=[]
        for it in d.natspec:
            kindname=it.kind[0]
            items.append(dbg_struct("NatSpecItem",[("kind",dbg_raw(self.natspec_kind(it))),("span",self.sp(it.span)),("content_start",dbg_raw(str(it.content_start))),("content_end",dbg_raw(str(it.content_end)))]))
        return dbg_struct("DocComment",[("kind",dbg_raw(d.kind)),("span",self.sp(d.span)),("symbol",dbg_str(d.symbol)),("natspec",dbg_list(items))])
    def natspec_kind(self,it):
        # TODO refine @param etc forms via dumps; simple variants for common tags
        return it.kind[0]
    def item(self,item):
        return dbg_struct("Item",[("docs",self.docs(item.docs)),("span",self.sp(item.span)),("kind",self.item_kind(item.item))])
    def item_kind(self,n):
        k=n.kind
        if k=="Pragma": return dbg_struct("ItemKind::PragmaDirective",[("tokens",self.pragma_tokens(n))])
        if k=="Import":
            path=dbg_struct("StrLit",[("span",self.sp(span_of(n.path_tok))),("value",dbg_str(n.path_symbol))])
            return dbg_struct("ItemKind::ImportDirective",[("path",path),("items",self.import_items(n))])
        if k=="Contract":
            fields=[("kind",dbg_raw(n.ckind)),("name",dbg_id(n.name)),("layout",dbg_opt(self.layout(n.layout) if n.layout else None)),("bases",dbg_list([self.modifier(b) for b in n.bases])),("body",dbg_list([self.item(x) for x in n.body]))]
            return dbg_struct("ItemKind::ItemContract",fields)
        if k=="Function":
            return dbg_struct("ItemKind::ItemFunction",[("kind",dbg_raw(n.fkind)),("header",self.func_header(n.header)),("body",dbg_opt(self.block(n.body) if n.body else None)),("body_span",self.sp(n.body_span))])
        if k=="VariableDefinition":
            return self.var_def_variant(n)
        if k=="Struct":
            return dbg_struct("ItemKind::Struct",[("name",dbg_id(n.name)),("fields",dbg_list([self.var_def_plain(f) for f in n.fields]))]) if False else self.struct_kind(n)
        if k=="Enum":
            return dbg_struct("ItemKind::Enum",[("name",dbg_id(n.name)),("variants",dbg_list([dbg_id(v) for v in n.variants]))])
        if k=="Udvt":
            return dbg_struct("ItemKind::Udvt",[("name",dbg_id(n.name)),("ty",self.ty(n.ty))]) if False else self.udvt_kind(n)
        if k=="ErrorDef":
            return dbg_struct("ItemKind::Error",[("name",dbg_id(n.name)),("parameters",self.param_list(n.parameters))]) if False else self.error_kind(n)
        if k=="Event":
            return self.event_kind(n)
        if k=="Using":
            return self.using_kind(n)
        return dbg_raw(f"/*{k}*/")
    def struct_kind(self,n):
        # Fill exact names from dumps below (placeholder replaced after inspection)
        return dbg_struct("ItemKind::Struct",[("name",dbg_id(n.name)),("fields",dbg_list([self.var_def_plain(f) for f in n.fields]))])
    def udvt_kind(self,n):
        return dbg_struct("ItemKind::Udvt",[("name",dbg_id(n.name)),("ty",self.ty(n.ty))])
    def error_kind(self,n):
        return dbg_struct("ItemKind::Error",[("name",dbg_id(n.name)),("parameters",self.param_list(n.parameters))])
    def event_kind(self,n):
        return dbg_struct("ItemKind::Event",[("name",dbg_id(n.name)),("parameters",self.param_list(n.parameters)),("anonymous",dbg_raw("true" if n.anonymous else "false"))])
    def using_kind(self,n):
        return dbg_raw("/*using*/")
    def layout(self,n):
        return dbg_struct("StorageLayoutSpecifier",[("span",self.sp(n.span)),("slot",self.expr(n.slot))])
    def pragma_tokens(self,n):
