    def raw_token_kind(self,t):
        if t.kind=="ident": return dbg_tuple("Ident",[dbg_str(t.text)])
        if t.kind=="int": return dbg_tuple("Literal",[dbg_raw("Integer"),dbg_str(t.text)])
        if t.kind=="rational": return dbg_tuple("Literal",[dbg_raw("Rational"),dbg_str(t.text)])
        if t.kind=="string":
            content=t.text[1:-1] if len(t.text)>=2 else ""
