        if t.kind=="hexstring":
            return dbg_tuple("Literal",[dbg_raw("HexStr"),dbg_str(t.text[4:-1] if len(t.text)>=5 else "")])
        if t.kind=="unicodestring":
            return dbg_tuple("Literal",[dbg_raw("UnicodeStr"),dbg_str(t.text[8:-1] if len(t.text)>=9 else "")])
        m={"+":("BinOp","Plus"),"-":("BinOp","Minus"),"*":("BinOp","Star"),"/":("BinOp","Slash"),"%":("BinOp","Percent"),"^":("BinOp","Caret"),"&":("BinOp","And"),"|":("BinOp","Or"),"<<":("BinOp","Shl"),">>":("BinOp","Shr"),"(":("OpenDelim","Parenthesis"),")":("CloseDelim","Parenthesis"),"[":("OpenDelim","Bracket"),"]":("CloseDelim","Bracket"),"{":("OpenDelim","Brace"),"}":("CloseDelim","Brace"),"=":("Eq",None),"<":("Lt",None),">":("Gt",None),"<=":("Le",None),">=":("Ge",None),"==":("EqEq",None),"!=":("Ne",None),"&&":("AndAnd",None),"||":("OrOr",None),"!":("Not",None),"~":("Tilde",None),".":("Dot",None),",":("Comma",None),";":("Semi",None),":":("Colon",None),"?":("Question",None)}
        if t.kind in m:
            name,arg=m[t.kind]
            return dbg_tuple(name,[dbg_raw(arg)]) if arg else dbg_raw(name)
        return dbg_raw(t.kind)
    def semver_req(self,req):
        if req is None: return dbg_raw("/*req*/")
        dis=[]
        for con in req.dis:
            comps=[]
            for comp in con.components:
                if comp.ckind[0]=="Op":
                    _,op,v=comp.ckind
                    opn=dbg_opt(dbg_raw(op) if op else None)
                    comps.append(dbg_struct("SemverReqComponent",[("span",self.sp(comp.span)),("kind",dbg_tuple("Op",[opn,self.semver_version(v)]))]))
                else:
                    _,lv,rv=comp.ckind
                    comps.append(dbg_struct("SemverReqComponent",[("span",self.sp(comp.span)),("kind",dbg_tuple("Range",[self.semver_version(lv),self.semver_version(rv)]))]))
            dis.append(dbg_struct("SemverReqCon",[("span",self.sp(con.span)),("components",dbg_list(comps))]))
        return dbg_struct("SemverReq",[("dis",dbg_list(dis))])
    def semver_version(self,v):
        return dbg_struct("SemverVersion",[("span",self.sp(v.span)),("version",dbg_raw(v.version))])
    def import_items(self,n):
        mode=n.items[0]
        if mode=="Plain":
            return dbg_tuple("Plain",[dbg_opt_id(n.items[1])])
        if mode=="Glob":
            return dbg_tuple("Glob",[dbg_id(n.items[1])])
        # Select
        entries=[]
        for name,alias in n.items[1]:
            entries.append(dbg_struct("ImportItem",[("name",dbg_id(name)),("alias",dbg_opt_id(alias))]) if False else self.import_item(name,alias))
        return dbg_tuple("Select",[dbg_list(entries)])
    def import_item(self,name,alias):
        # exact form inspected from dump later
        return dbg_tuple_plain([dbg_id(name),dbg_opt_id(alias)])
    def modifier(self,n):
        return dbg_struct("Modifier",[("name",self.ast_path(n.name)),("arguments",self.call_args(n.arguments))])
    def ast_path(self,parts):
        return dbg_tuple("AstPath",[dbg_list([dbg_id(x) for x in parts])])
    def ast_path_compact(self,parts):
        inner=", ".join(x.name for x in parts)
        return dbg_raw(f"AstPath([{inner}])")
    def call_args(self,n):
        if n.kind=="Unnamed":
            kind=dbg_tuple("Unnamed",[dbg_list([self.expr(a) for a in n.args])])
        else:
