        return dbg_struct("FunctionHeader",fields)
    def override(self,n):
        return dbg_struct("Override",[("span",self.sp(n.span)),("paths",dbg_list([self.ast_path(p) for p in n.paths]))]) if False else self.override_real(n)
    def override_real(self,n):
