            return dbg_tuple("Plain",[dbg_opt_id(n.items[1])])
        if mode=="Glob":
            return dbg_tuple("Glob",[dbg_id(n.items[1])])
        # Select
        entries=[]
        for name,alias in n.items[1]:
            entries.append(dbg_struct("ImportItem",[("name",dbg_id(name)),("alias",dbg_opt_id(alias))]) if False else self.import_item(name,alias))
        return dbg_tuple("Select",[dbg_list(entries)])
    def import_item(self,name,alias):
        # exact form inspected from dump later
        return dbg_tuple_plain([dbg_id(name),dbg_opt_id(alias)])
    def modifier(self,n):
        return dbg_struct("Modifier",[("name",self.ast_path(n.name)),("arguments",self.call_args(n.arguments))])
    def ast_path(self,parts):
        return dbg_tuple("AstPath",[dbg_list([dbg_id(x) for x in parts])])
    def ast_path_compact(self,parts):
        inner=", ".join(x.name for x in parts)
        return dbg_raw(f"AstPath([{inner}])")
