    def var_def_plain(self,n):
        return dbg_struct("VariableDefinition",self.var_def_fields(n))
    def var_def_variant(self,n):
        return dbg_struct("ItemKind::VariableDefinition",self.var_def_fields(n))
    def ty(self,n):
        if n is None: return dbg_raw("/*ty*/")
        return dbg_struct("Type",[("span",self.sp(n.span)),("kind",self.ty_kind(n))])
    def ty_kind(self,n):
        tk=n.tkind
        if tk[0]=="elem":
            e=tk[1]
            if e[0]=="uint": return dbg_raw(f"UInt({e[1]})")
            if e[0]=="int": return dbg_raw(f"Int({e[1]})")
            if e[0]=="address": return dbg_raw("Address")
            if e[0]=="address_payable": return dbg_raw("AddressPayable")
            if e[0]=="bool": return dbg_raw("Bool")
            if e[0]=="bytes": return dbg_raw("Bytes")
            if e[0]=="fixedbytes": return dbg_raw(f"FixedBytes({e[1]})")
            if e[0]=="string": return dbg_raw("String")
            if e[0]=="fixed": return dbg_raw(f"Fixed({e[1]}, {e[2]})")
            if e[0]=="ufixed": return dbg_raw(f"UFixed({e[1]}, {e[2]})")
        if tk[0]=="array":
            _,elem,size=tk
            return dbg_struct("TypeArray",[("element",self.ty(elem)),("size",dbg_opt(self.expr(size) if size else None))])
        if tk[0]=="mapping":
            _,key,kn,val,vn=tk
            return dbg_struct("TypeMapping",[("key",self.ty(key)),("key_name",dbg_opt_id(kn)),("value",self.ty(val)),("value_name",dbg_opt_id(vn))])
        if tk[0]=="custom":
            return dbg_raw(f"Custom({self.ast_path_compact(tk[1])[1]})")
        if tk[0]=="function":
            _,params,vis,mut,rets=tk
            return dbg_struct("TypeFunction",[("parameters",self.param_list(params)),("visibility",self.spanned(vis)),("state_mutability",self.spanned(mut)),("returns",dbg_opt(self.param_list(rets) if rets else None))])
        return dbg_raw("/*tkind*/")
    # Expressions/statements are implemented in a following section.
    def expr(self,n):
        return dbg_expr(self,n)
    def block(self,n):
        return dbg_block(self,n)
    def stmt(self,n):
        return dbg_stmt(self,n)

def dump_parsed_sources(compiler):
    return format_dbg(AstDbg(compiler).sources())+"\n"
def dump_one_source(compiler,src):
    return format_dbg(AstDbg(compiler).source(src))+"\n"

