import subprocess,re,itertools,json
ops=["||","&&","==","!=","<",">","<=",">=","|","^","&","<<",">>",">>>","+","-","*","/","%","**"]
names={"||":"Or","&&":"And","==":"Eq","!=":"Ne","<":"Lt",">":"Gt","<=":"Le",">=":"Ge","|":"BitOr","^":"BitXor","&":"BitAnd","<<":"Shl",">>":"Shr",">>>":"Sar","+":"Add","-":"Sub","*":"Mul","/":"Div","%":"Rem","**":"Pow"}
def root_and_side(e):
 s=f"contract C{{ function f() public {{ uint x = {e}; }} }}"
 p=subprocess.run(["./executable","-","-Zdump=ast"],input=s,capture_output=True,text=True)
 bins=[(int(a),int(b)) for a,b in re.findall(r"span: <stdin>:1:(\d+): 1:(\d+),\n\s+kind: Binary\(",p.stdout)]
 oks=re.findall(r"BinOp \{\n\s+span: [^,]+,\n\s+kind: (\w+)",p.stdout)
 if len(bins)<2: return None
 side="left" if bins[1][0]==bins[0][0] else "right"
 return oks[1] if side=="left" else oks[0]
rel={}
for x,y in itertools.permutations(ops,2):
    r=root_and_side(f"a {x} b {y} c")
    rel[(x,y)]=r
# classify unordered pairs
classes=[]
for x,y in itertools.combinations(ops,2):
    r1=rel[(x,y)]; r2=rel[(y,x)]
    if r1==names[x] and r2==names[y]: cls="equal-right-or-firstroot"
    elif r1==names[y] and r2==names[x]: cls="equal-left-or-secondroot"
    elif r1==r2==names[x]: cls=f"{x} lower than {y}"
    elif r1==r2==names[y]: cls=f"{y} lower than {x}"
    else: cls=f"weird {r1} {r2}"
    classes.append((x,y,cls))
from collections import Counter
print(Counter(c for _,_,c in classes if c.startswith("equal") or c.startswith("weird")))
for row in classes:
    if not (" lower than " in row[2]): print(row)
# Build lower-than graph and topological-ish ranks: score = number of ops it is lower than? If x lower than y, x should come before.
lowers={o:set() for o in ops}
for x,y,c in classes:
    if c==f"{x} lower than {y}": lowers[x].add(y)
    if c==f"{y} lower than {x}": lowers[y].add(x)
print("lower counts")
for o in ops: print(o, len(lowers[o]), sorted(lowers[o]))
json.dump({f"{k[0]}|{k[1]}":v for k,v in rel.items()},open("/tmp/prec.json","w"))
