                args=[]
                if bmod.arguments and bmod.arguments.args:
                    for a in bmod.arguments.args: args.append(self.lower_expr(a,c.source_fid,None,None,[]))
                bases_args.append(args)
            c.bases_ents=bases_ents; c.bases_args_ents=bases_args
            c.bases=[e for e in bases_ents if e is not None]
            c.bases_args=bases_args
