    def linearize(self,contract):
        # C3 linearization, contracts in order: derived first, then merge base linearizations reversed base order (Solidity is most-derived-first)
        # If a cycle exists, analysis errors are emitted elsewhere; return a simple order to avoid loops.
        try:
            return self._c3(contract,[])
        except Exception:
            return [contract]
    def _c3(self,contract,stack):
        if contract in stack:
            return [contract]
        stack=stack+[contract]
        bases=[b for b in getattr(contract,"bases_ents",[]) if b is not None]
        if not bases: return [contract]
        seqs=[self._c3(b,stack) for b in bases]
        seqs.append(list(bases))
        merged=self._c3_merge(seqs)
        return [contract]+merged
    def _c3_merge(self,seqs):
        seqs=[list(s) for s in seqs]
        out=[]
        while True:
            seqs=[s for s in seqs if s]
            if not seqs: break
            found=None
            for s in seqs:
                head=s[0]
                if any(head in other[1:] for other in seqs): continue
                found=head; break
            if found is None:
                # linearization failure (diagnosed in analysis pass)
                # append remaining first heads to make progress
                found=seqs[0][0]
            out.append(found)
            for s in seqs:
                if s and s[0] is found: s.pop(0)
        return out

def fmt_allowed(allowed):
    lst=[f"`{a}`" for a in allowed]
    # 'none' is written as `none` in original notes too
    return fmt_expected(lst)

