    def make_path_call_expr(self,parts,ast_args,src_fid,contract,function,local_scopes,call_span):
        # Build callee as Ident/Member chain, resolving the whole path for unresolved diagnostics.
        # Resolve full path for diagnostics but keep Res of final entity on the last Ident like AST->HIR single ident calls.
        # For a single segment, callee Ident Res is the resolved entity(ies).
        final_ent=self.resolve_path(parts,src_fid,contract)
        # Build base expr
        first=parts[0]
        if len(parts)==1:
            res=[("item",final_ent)] if final_ent is not None else []
            if not res:
                # resolve_path already emitted unresolved; still make an Err callee? Original likely Err expr for whole call - simplify to Ident with empty res
                callee=self.mk_expr(first.span,("Err",))
            else:
                callee=self.mk_expr(first.span,("Ident",res,first))
        else:
            base_res=self.resolve_ident_entries(first.name,src_fid,contract,local_scopes)
            if base_res:
                callee=self.mk_expr(first.span,("Ident",base_res,first))
            else:
                callee=self.mk_expr(first.span,("Err",))
            for seg in parts[1:]:
                callee=self.mk_expr((span_join(callee.span,seg.span)),("Member",callee,seg))
        args=self.lower_call_args(ast_args,src_fid,contract,function,local_scopes)
        return self.mk_expr(call_span,("Call",callee,args))
