        seen_memory_safe=False
        for f in flags:
            if f.value=="memory-safe":
                if seen_memory_safe:
                    self.hir.err("inline assembly marked memory-safe multiple times",f.span)
                seen_memory_safe=True
            else:
                self.hir.warn("unknown inline assembly flag",f.span)
