                rv=self.hir.add("variable",source_fid=fn.source_fid,contract=fn.contract,function=fn,span=var.span,vkind="FunctionReturn",ast=dummy,ty=f.ty,name=f.name,visibility=None,mutability=None,data_location=None,override_ast=None,overrides=[],indexed=False,initializer=None,getter=None,lowered=True)
                fn.returns.append(rv)
