        vars_snapshot=list(self.hir.variables)
        for var in vars_snapshot:
            if getattr(var,"lowered",False): continue
            # For UDVT underlying types & struct recursion checks do after variables? UDVT handled separately.
            self.lower_variable(var,var.source_fid,var.contract,var.function,[])
