    def check_recursive_structs(self):
        # For each struct field whose type directly (not through array/mapping) is a struct, detect cycles.
        # Original emits one error per struct field that forms a cycle (mutual gives 2).
        for st in self.hir.structs:
            for f in st.fields:
                if f.ty is not None and f.ty.tkind[0]=="custom" and isinstance(f.ty.tkind[1],Ent) and f.ty.tkind[1].cat=="struct":
                    if self._struct_reaches(f.ty.tkind[1],st,[]):
                        self.hir.err("recursive struct definition",f.ty.span)
    def _struct_reaches(self,cur,target,seen):
        if cur is target: return True
        if cur.eid in seen: return False
        seen=seen+[cur.eid]
        for f in cur.fields:
            if f.ty is not None and f.ty.tkind[0]=="custom" and isinstance(f.ty.tkind[1],Ent) and f.ty.tkind[1].cat=="struct":
                if self._struct_reaches(f.ty.tkind[1],target,seen): return True
        return False

