        if c in stack: return (False,[])
        stack=stack+[c]
        bases=[b for b in getattr(c,"bases_ents",[]) if b is not None]
        seqs=[]
        for b in bases:
            ok,l=self._c3_checked(b,stack)
            if not ok: return (False,[])
            seqs.append(l)
        seqs.append(list(bases))
        # merge
        out=[]; seqs=[list(s) for s in seqs]
        while True:
            seqs=[s for s in seqs if s]
            if not seqs: break
            found=None
            for s in seqs:
                head=s[0]
                if any(head in o[1:] for o in seqs): continue
                found=head; break
            if found is None: return (False,[])
            out.append(found)
            for s in seqs:
                if s and s[0] is found: s.pop(0)
        return (True,[c]+out)

def fmt_name_list(names):
    items=[f"`{n}`" for n in names]
    if len(items)==1: return items[0]
    if len(items)==2: return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1])+", and "+items[-1]

