        # merge
        out=[]; seqs=[list(s) for s in seqs]
        while True:
            seqs=[s for s in seqs if s]
            if not seqs: break
            found=None
            for s in seqs:
                head=s[0]
                if any(head in o[1:] for o in seqs): continue
                found=head; break
            if found is None: return (False,[])
            out.append(found)
