    if e[0]=="uint": return f"UInt({e[1]})"
    if e[0]=="int": return f"Int({e[1]})"
    if e[0]=="address": return "Address"
    if e[0]=="address_payable": return "AddressPayable"
    if e[0]=="bool": return "Bool"
    if e[0]=="bytes": return "Bytes"
    if e[0]=="fixedbytes": return f"FixedBytes({e[1]})"
    if e[0]=="string": return "String"
    if e[0]=="fixed": return f"Fixed({e[1]}, {e[2]})"
    if e[0]=="ufixed": return f"UFixed({e[1]}, {e[2]})"
    return e[0]

def do_dump_hir_impl(compiler,hir,paths):
    if hir is None or getattr(compiler,"hir_poisoned",False): return
    out=format_dbg(HirDbg(compiler,hir).root())+"\n"
    sys.stdout.write(out)
    if paths is not None:
        sys.stdout.write("\nPaths not yet implemented: [\n")
        for pth in paths: sys.stdout.write(f"    {rust_debug_str(pth)},\n")
        sys.stdout.write("]\n")
    sys.stdout.flush()

