# ============================= ABI generation =============================
_KECCAK_RC=[0x0000000000000001,0x0000000000008082,0x800000000000808A,0x8000000080008000,0x000000000000808B,0x0000000080000001,0x8000000080008081,0x8000000000008009,0x000000000000008A,0x0000000000000088,0x0000000080008009,0x000000008000000A,0x000000008000808B,0x800000000000008B,0x8000000000008089,0x8000000000008003,0x8000000000008002,0x8000000000000080,0x000000000000800A,0x800000008000000A,0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
_KECCAK_R=[[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
def _rol64(x,n): return ((x<<n)|(x>>(64-n))) & ((1<<64)-1) if n else x & ((1<<64)-1)
def _keccak_f(state):
    for rc in _KECCAK_RC:
        c=[state[x]^state[x+5]^state[x+10]^state[x+15]^state[x+20] for x in range(5)]
        d=[c[(x-1)%5]^_rol64(c[(x+1)%5],1) for x in range(5)]
        for x in range(5):
            for y in range(5): state[x+5*y]^=d[x]
        b=[0]*25
        for x in range(5):
            for y in range(5):
                b[y+5*((2*x+3*y)%5)]=_rol64(state[x+5*y],_KECCAK_R[x][y])
        for x in range(5):
            for y in range(5):
                state[x+5*y]=b[x+5*y]^((~b[(x+1)%5+5*y]) & b[(x+2)%5+5*y]) & ((1<<64)-1)
        state[0]^=rc
def keccak256(data):
    rate=136; state=[0]*25
    # pad10*1 with Keccak domain suffix 0x01
    padded=bytearray(data); padded.append(0x01)
    while len(padded)%rate!=rate-1: padded.append(0)
    padded.append(0x80)
    for off in range(0,len(padded),rate):
        block=padded[off:off+rate]
        for i in range(rate//8):
            state[i]^=int.from_bytes(block[i*8:(i+1)*8],'little')
        _keccak_f(state)
    out=bytearray()
    while len(out)<32:
        for i in range(rate//8): out.extend(state[i].to_bytes(8,'little'))
        if len(out)>=32: break
        _keccak_f(state)
    return bytes(out[:32])

class AbiGen:
    def __init__(self,sema):
        self.sema=sema; self.hir=sema.hir
    def internal_type(self,hty):
        if hty is None: return "?"
        tk=hty.tkind
        if tk[0]=="elem":
            e=tk[1]
            if e[0]=="uint": return f"uint{e[1] or 256}"
            if e[0]=="int": return f"int{e[1] or 256}"
            if e[0]=="address": return "address"
            if e[0]=="address_payable": return "address payable"
            if e[0]=="bool": return "bool"
            if e[0]=="bytes": return "bytes"
            if e[0]=="fixedbytes": return f"bytes{e[1]}"
            if e[0]=="string": return "string"
            if e[0]=="fixed": return f"fixed{e[1]}x{e[2]}" if False else "fixed256x0"
            if e[0]=="ufixed": return "ufixed256x0"
        if tk[0]=="array":
            sz=""
            if tk[2] is not None:
                v=self.sema.const_eval_hir(tk[2]); sz=str(v) if isinstance(v,int) else ""
            return self.internal_type(tk[1])+f"[{sz}]"
        if tk[0]=="mapping":
            kn=f" {tk[2].name}" if tk[2] else ""; vn=f" {tk[4].name}" if tk[4] else ""
            return f"mapping({self.internal_type(tk[1])}{kn} => {self.internal_type(tk[3])}{vn})"
        if tk[0]=="custom":
            ent=tk[1]
            if not isinstance(ent,Ent): return "?"
            prefix={"struct":"struct ","enum":"enum ","contract":"contract ","udvt":""}.get(ent.cat,"")
            if ent.contract: return f"{prefix}{ent.contract.name.name}.{ent.name.name}"
            return f"{prefix}{ent.name.name}"
        if tk[0]=="function":
            d=tk[1]
            ps=", ".join(self.internal_type(v.ty) for v in d["params"])
            s=f"function ({ps}) {d['visibility'].lower()}"
            if d["mutability"]!="NonPayable": s+=f" {d['mutability'].lower()}"
            if d["returns"]:
                rs=", ".join(self.internal_type(v.ty) for v in d["returns"]); s+=f" returns ({rs})"
            return s
        return "?"
    def abi_type(self,hty):
        """returns (type_name, components_or_None)"""
        if hty is None: return ("?",None)
        tk=hty.tkind
        if tk[0]=="elem":
            e=tk[1]
            if e[0]=="address_payable": return ("address",None)
            return (self.internal_type(hty),None)
        if tk[0]=="array":
            b,c=self.abi_type(tk[1]); sz=""
            if tk[2] is not None:
                v=self.sema.const_eval_hir(tk[2]); sz=str(v) if isinstance(v,int) else ""
            return (f"{b}[{sz}]",c)
        if tk[0]=="custom":
            ent=tk[1]
            if isinstance(ent,Ent):
                if ent.cat=="struct":
                    comps=[self.param(f.name.name if f.name else "",f.ty) for f in ent.fields]
                    return ("tuple",comps)
                if ent.cat=="enum": return ("uint8",None)
                if ent.cat=="udvt": return self.abi_type(ent.ty)
                if ent.cat=="contract": return ("address",None)
            return ("?",None)
        if tk[0]=="function": return ("function",None)
        if tk[0]=="mapping":
            return ("mapping",None)
        return ("?",None)
    def param(self,name,hty,indexed=None):
        t,comps=self.abi_type(hty)
        d={"name":name}; d["type"]=t
        if indexed is not None: d["indexed"]=indexed
        d["internalType"]=self.internal_type(hty)
        if comps is not None: d["components"]=comps
        return d
    def fn_entry(self,fn):
        return {"type":"function","name":fn.name.name if fn.name else "","inputs":[self.param(v.name.name if v.name else "",v.ty) for v in fn.parameters],"outputs":[self.param(v.name.name if v.name else "",v.ty) for v in fn.returns],"stateMutability":fn.state_mutability.lower()}
    def signature(self,fn):
        return f"{fn.name.name if fn.name else ''}("+",".join(self.sema.canonical_ty_str(v.ty) for v in fn.parameters)+")"
    def contract_abi(self,c):
        entries=[]; hashes={}
        # functions: most derived definition per signature wins
        seen_sig={}
        fn_entries=[]
        for bc in (c.linearized or [c]):
            for fn in [f for f in self.hir.functions if f.contract is bc]:
                if fn.fkind!="Function": continue
                if fn.visibility not in ("Public","External"): continue
                sig=self.signature(fn)
                if sig in seen_sig: continue
                seen_sig[sig]=fn; fn_entries.append(fn)
        for fn in fn_entries:
            entries.append(self.fn_entry(fn))
            hashes[self.signature(fn)]=keccak256(self.signature(fn).encode())[:4].hex()
        # constructor (own only)
        if c.ctor is not None:
            entries.append({"type":"constructor","inputs":[self.param(v.name.name if v.name else "",v.ty) for v in c.ctor.parameters],"stateMutability":c.ctor.state_mutability.lower()})
        # fallback / receive (first in linearized)
        for attr,typ in [("fallback","fallback"),("receive","receive")]:
            found=None
            for bc in (c.linearized or [c]):
                f=getattr(bc,attr)
                if f is not None: found=f; break
            if found is not None:
                entries.append({"type":typ,"stateMutability":found.state_mutability.lower()})
        # events & errors from whole chain
        for bc in (c.linearized or [c]):
            for ev in [e for e in self.hir.events if e.contract is bc]:
                entries.append({"type":"event","name":ev.name.name,"inputs":[self.param(v.name.name if v.name else "",v.ty,indexed=bool(v.indexed)) for v in ev.parameters],"anonymous":bool(ev.anonymous)})
            for er in [e for e in self.hir.errors if e.contract is bc]:
                entries.append({"type":"error","name":er.name.name,"inputs":[self.param(v.name.name if v.name else "",v.ty) for v in er.parameters]})
        entries.sort(key=lambda e:(e.get("type",""),e.get("name","")))
        return entries,dict(sorted(hashes.items()))
    def combined(self):
        contracts={}
        for c in self.hir.contracts:
            src=self.hir.c.sources[c.source_fid]
            abi,hashes=self.contract_abi(c)
            entry={}
            if "abi" in self.hir.c.opts.emit: entry["abi"]=abi
            if "hashes" in self.hir.c.opts.emit: entry["hashes"]=hashes
            contracts[f"{src.name}:{c.name.name}"]=entry
        out={}
        if contracts: out["contracts"]=dict(sorted(contracts.items()))
        out["version"]=VERSION
        return out

