def max_storage_slots(sema,hty,seen=None):
    if hty is None: return 1
    tk=hty.tkind
    if tk[0]=="array":
        if tk[2] is None: return 1
        v=sema.const_eval_hir(tk[2])
        return (v if isinstance(v,int) else 1)*max_storage_slots(sema,tk[1],seen)
    if tk[0]=="custom" and isinstance(tk[1],Ent) and tk[1].cat=="struct":
        seen=seen or set()
        if tk[1].eid in seen: return 1
        seen=set(seen)|{tk[1].eid}
        return 1+sum(max_storage_slots(sema,f.ty,seen) for f in tk[1].fields)
    if tk[0]=="custom" and isinstance(tk[1],Ent) and tk[1].cat=="udvt":
        return max_storage_slots(sema,tk[1].ty,seen)
    return 1

def do_print_max_storage_impl(compiler,hir):
    if hir is None: return
    sema=compiler.sema
    for c in hir.contracts:
        total=0
        for bc in reversed(c.linearized or [c]):
            for v in hir.variables:
                if v.contract is bc and v.vkind=="State":
                    if v.mutability and v.mutability[0] in ("Constant","Immutable"): continue
                    total+=max_storage_slots(sema,v.ty)
        src=compiler.sources[c.source_fid]
        d=Diag("note",f"{src.name}:{c.name.name} requires a maximum of {total} storage slots",spans=[sd(c.name.span)])
        compiler.dcx.emit(d)

