            for kind,val in callee.ekind[1]:
                if kind=="item" and isinstance(val,Ent) and val.cat=="function": cands.append(val)
        elif callee.ekind[0]=="Member":
            # resolve member function via base contract if base is This/contract ident/super - approximate via name search in all contracts
            mname=callee.ekind[2].name
