class Typeck:
    def __init__(self,compiler,hir):
        self.c=compiler; self.hir=hir; self.dcx=compiler.dcx; self.sema=compiler.sema
    def err_mismatch(self,span,expected,found):
        d=Diag("error","mismatched types",spans=[SpanData(span[0],span[1],span[2],f"expected `{expected}`, found `{found}`",True)]); self.dcx.emit(d)
    def ty_name(self,t):
        if t is None: return "?"
        k=t[0]
        if k=="elem":
            return AbiGen(self.sema).internal_type(Node("HType",None,tkind=t)) if False else self.elem_name(t[1])
        if k=="intlit": return f"int_literal[{t[1]}]"
        if k=="strlit": return f"utf8_string_literal[{t[1]}]"
        if k=="hexlit": return f"bytes_string_literal[{t[1]}]"
        if k=="array":
            loc=f" {t[3]}" if t[3] else ""
            return self.ty_name(t[1])+f"[{t[2] if t[2] is not None else ''}]"+loc
        if k=="custom":
            e=t[1]
            if e.cat=="struct":
                loc=f" {t[2]}" if len(t)>2 and t[2] else ""
                pfx=f"struct {e.contract.name.name}." if getattr(e,"contract",None) else "struct "
                return pfx+e.name.name+loc
            if e.cat=="enum":
                return f"enum {e.contract.name.name}.{e.name.name}" if getattr(e,"contract",None) else f"enum {e.name.name}"
            if e.cat=="contract": return f"contract {e.name.name}"
            return e.name.name
        if k=="builtin": return t[1]
        if k=="tuple": return "("+", ".join(self.ty_name(x) for x in t[1])+")"
        if k=="function": return "function"
        if k=="mapping": return "mapping"
        return str(t)
    def elem_name(self,e):
        if e[0]=="uint": return f"uint{e[1] or 256}"
        if e[0]=="int": return f"int{e[1] or 256}"
        if e[0]=="address": return "address"
        if e[0]=="address_payable": return "address payable"
        if e[0]=="bool": return "bool"
        if e[0]=="bytes": return "bytes"
        if e[0]=="fixedbytes": return f"bytes{e[1]}"
        if e[0]=="string": return "string"
        if e[0]=="fixed": return "fixed256x0"
        if e[0]=="ufixed": return "ufixed256x0"
        return e[0]
    def from_hir_ty(self,hty,dl=None):
        if hty is None: return None
        tk=hty.tkind
        if tk[0]=="elem":
            base=("elem",tk[1])
            if tk[1][0] in ("string","bytes"):
                return ("elemloc",tk[1],dl)
            return base
        if tk[0]=="array":
            sz=self.sema.const_eval_hir(tk[2]) if tk[2] is not None else None
            return ("array",self.from_hir_ty(tk[1]),sz if isinstance(sz,int) else None,dl)
        if tk[0]=="custom":
            ent=tk[1]
            if isinstance(ent,Ent) and ent.cat=="struct": return ("custom",ent,dl)
            return ("custom",ent)
        if tk[0]=="mapping": return ("mapping",)
        if tk[0]=="function": return ("function",tk[1])
        return None
    def var_ty(self,v):
        dl=v.data_location[0].lower() if v.data_location else None
        return self.from_hir_ty(v.ty,dl)
    def compatible(self,expected,found):
        if expected is None or found is None: return True
        if expected==found: return True
        # int literal fits
        if found[0]=="intlitval":
            val,bits=found[1],found[2]
            if expected[0]=="elem":
                e=expected[1]
                if e[0]=="uint": return val>=0 and val < (1<<(e[1] or 256))
                if e[0]=="int":
                    n=e[1] or 256; return -(1<<(n-1))<=val<(1<<(n-1))
                if e[0]=="fixedbytes": return val>=0 and val < (1<<(8*e[1]))
            return False
        if found[0]=="strlit":
            return expected[0] in ("elemloc","elem") and expected[1][0] in ("string","bytes") or (expected[0]=="elem" and expected[1][0]=="fixedbytes" and found[1]==expected[1][1])
        if found[0]=="hexlit":
            if expected[0] in ("elemloc","elem") and expected[1][0]=="bytes": return True
            return expected[0]=="elem" and expected[1][0]=="fixedbytes" and found[1]==expected[1][1]
        if expected[0]=="elem" and found[0]=="elem":
            a,b=expected[1],found[1]
            if a[0]=="uint" and b[0]=="uint": return (b[1] or 256)<=(a[1] or 256)
            if a[0]=="int" and b[0]=="int": return (b[1] or 256)<=(a[1] or 256)
            if a[0]=="int" and b[0]=="uint": return (b[1] or 256)<(a[1] or 256)
            if a[0]=="address" and b[0]=="address_payable": return True
            if a[0]=="fixedbytes" and b[0]=="fixedbytes": return b[1]<=a[1]
            return False
        if expected[0]=="elemloc" or found[0]=="elemloc":
            # string/bytes with locations: types must match ignoring location for assignments (memory<->calldata copies are allowed in solc; WIP may be stricter for call args handled separately)
            en=expected[1] if expected[0] in ("elem","elemloc") else None; fn=found[1] if found[0] in ("elem","elemloc") else None
            return en is not None and en==fn
        if expected[0]=="array" and found[0]=="array":
            return self.compatible(expected[1],found[1])
        if expected[0]=="custom" and found[0]=="custom":
            return expected[1] is found[1]
        if expected==("elem",("address",)) and found[0]=="custom" and isinstance(found[1],Ent) and found[1].cat=="contract": return True
        return False
    def display_found(self,t):
        if t is not None and t[0]=="intlitval": return f"int_literal[{t[2]}]"
        if t is not None and t[0]=="elemloc":
            loc=f" {t[2]}" if t[2] else ""
            return self.elem_name(t[1])+loc
        return self.ty_name(t)
    def display_expected(self,t):
        return self.display_found(t)
    def check_assign(self,span,expected,found):
        if expected is None or found is None: return
        if not self.compatible(expected,found):
            self.err_mismatch(span,self.display_expected(expected),self.display_found(found))
    def run(self):
        # variable initializers
        for v in self.hir.variables:
            if v.initializer is not None:
                ft=self.infer(v.initializer)
                self.check_assign(v.initializer.span,self.var_ty(v),ft)
        for fn in self.hir.functions:
            if fn.body: self.check_block(fn.body)
    def check_block(self,blk):
        for s in blk.stmts: self.check_stmt(s)
    def check_stmt(self,s):
        sk=s.skind; t=sk[0]
        if t=="Expr": self.infer(sk[1])
        elif t=="Return":
            if sk[1] is not None: self.infer(sk[1])
        elif t=="DeclSingle":
            pass # initializer checked in variables loop
        elif t=="DeclMulti":
            self.infer(sk[2])
        elif t=="If":
            self.infer(sk[1]); self.check_stmt(sk[2])
            if sk[3]: self.check_stmt(sk[3])
        elif t=="Block": self.check_block(sk[1])
        elif t=="UncheckedBlock": self.check_block(sk[1])
        elif t=="While": self.infer(sk[1]); self.check_stmt(sk[2])
        elif t=="DoWhile": self.check_stmt(sk[1]); self.infer(sk[2])
        elif t=="For":
            if sk[1]: self.check_stmt(sk[1])
            if sk[2]: self.infer(sk[2])
            if sk[3]: self.infer(sk[3])
            self.check_stmt(sk[4])
        elif t=="Emit": self.infer(sk[1])
        elif t=="Revert": self.infer(sk[1])
        elif t=="Try":
            self.infer(sk[1])
            for c in sk[2]: self.check_block(c.block)
    def infer(self,e):
        if e is None: return None
        ek=e.ekind; t=ek[0]
        if t=="Err": return None
        if t=="Lit":
            lit=ek[1]; lk=lit.lkind
            if lk[0]=="Number":
                v=lk[1]; bits=max(1,v.bit_length()) if isinstance(v,int) else 1
                return ("intlitval",v,bits)
            if lk[0]=="Rational":
                self.dcx.emit(Diag("error","rational literals are not supported",spans=[sd(e.span)])); return None
            if lk[0]=="Bool": return ("elem",("bool",))
            if lk[0]=="Str":
                # WIP bug: literal size reported is sometimes 32 for short strings in call contexts; observed 'abc' -> [3] in assignments. Use byte length.
                return ("strlit",len(lk[1]))
            if lk[0]=="Hex": return ("hexlit",len(lk[1]))
            if lk[0]=="Unicode": return ("strlit",len(lk[1].encode()))
            return None
        if t=="Ident":
            res=ek[1]
            if not res: return None
            kind,val=res[0]
            if kind=="builtin": return ("builtin",val.lower())
            if kind=="item":
                ent=val
                if isinstance(ent,Ent):
                    if ent.cat=="variable": return self.var_ty(ent)
                    if ent.cat=="function": return ("function",ent)
                    if ent.cat in ("contract","struct","enum","udvt"): return ("custom",ent)
            return None
        if t=="Binary":
            lt=self.infer(ek[1]); rt=self.infer(ek[4]); op=ek[2]
            if lt is None or rt is None: return lt or rt
            # literal coercion
            if lt[0]=="intlitval" and rt[0]!="intlitval":
                if self.compatible(rt,lt): lt=rt
            elif rt[0]=="intlitval" and lt[0]!="intlitval":
                if self.compatible(lt,rt): rt=lt
            if op in ("&&","||"):
                if not (self._is_bool(lt) and self._is_bool(rt)):
                    self.op_error(e,op,lt,rt)
                return ("elem",("bool",))
            if op in ("==","!=","<",">","<=",">="):
                return ("elem",("bool",))
            if not self._same_numeric(lt,rt):
                self.op_error(e,op,lt,rt); return lt
            return lt if lt[0]!="intlitval" else rt
        if t=="Assign":
            lt=self.infer(ek[1]); rt=self.infer(ek[4])
            self.check_assign(ek[4].span,lt,rt)
            return lt
        if t=="Unary":
            et=self.infer(ek[3])
            if ek[1]=="-" and et is not None and et[0]=="intlitval":
                v=-et[1]; return ("intlitval",v,max(1,abs(v).bit_length()+1))
            if ek[1]=="!": return ("elem",("bool",))
            return et
        if t=="Delete": self.infer(ek[1]); return None
        if t=="Ternary":
            self.infer(ek[1]); a=self.infer(ek[2]); b=self.infer(ek[3]); return a or b
        if t=="Member":
            return self.infer_member(e)
        if t=="Call":
            return self.infer_call(e)
        if t=="Index":
            bt=self.infer(ek[1]); 
            if ek[2] is not None: self.infer(ek[2])
            if bt is not None and bt[0]=="array": return bt[1]
            if bt is not None and bt[0]=="mapping": return None
            if bt is not None and bt[0] in ("elemloc","elem") and bt[1][0] in ("bytes","string"): return ("elem",("fixedbytes",1))
            return None
        if t=="Tuple":
            ts=[self.infer(x) if x is not None else None for x in ek[1]]
            return ts[0] if len(ts)==1 else ("tuple",ts)
        if t=="Array":
            ts=[self.infer(x) for x in ek[1]]
            base=ts[0] if ts else None
            return ("array",base,len(ts),None)
        if t=="New":
            return self.from_hir_ty(ek[1])
        if t=="Type":
            return self.from_hir_ty(ek[1])
        if t=="TypeCall":
            return ("builtin","type")
        if t=="Payable":
            args=[self.infer(a) for a in ek[1].args]
            return ("elem",("address_payable",))
        return None
    def _is_bool(self,t): return t==("elem",("bool",))
    def _same_numeric(self,a,b):
        if a is None or b is None: return True
        if a[0]=="intlitval" and b[0]=="intlitval": return True
        return a==b
    def op_error(self,e,op,lt,rt):
        ek=e.ekind
        spans=[SpanData(ek[1].span[0],ek[1].span[1],ek[1].span[2],self.display_found(lt),False),SpanData(ek[4].span[0],ek[4].span[1],ek[4].span[2],self.display_found(rt),False),sd(ek[3])]
        self.dcx.emit(Diag("error",f"cannot apply builtin operator `{op}` to `{self.display_found(lt)}` and `{self.display_found(rt)}`",spans=spans))
    def infer_member(self,e):
        base=e.ekind[1]; member=e.ekind[2].name
        bt=self.infer(base)
        if bt is None: return None
        if bt[0]=="builtin":
            obj=bt[1]
            members={
             "msg":{"sender":("elem",("address",)),"value":("elem",("uint",0)),"data":("elemloc",("bytes",),"calldata"),"sig":("elem",("fixedbytes",4))},
             "block":{"timestamp":("elem",("uint",0)),"number":("elem",("uint",0)),"difficulty":("elem",("uint",0)),"prevrandao":("elem",("uint",0)),"coinbase":("elem",("address",)),"gaslimit":("elem",("uint",0)),"chainid":("elem",("uint",0)),"basefee":("elem",("uint",0)),"blobbasefee":("elem",("uint",0))},
             "tx":{"origin":("elem",("address",)),"gasprice":("elem",("uint",0))},
            }
            if obj in members:
                if member in members[obj]: return members[obj][member]
                self.dcx.emit(Diag("error",f"member `{member}` not found on type `{obj}`",spans=[sd(e.ekind[2].span)])); return None
            if obj=="abi":
                return ("builtinfn",member)
            if obj in ("this","super"):
                return None
            return None
        if bt[0]=="array" and member=="length": return ("elem",("uint",0))
        if bt[0] in ("elemloc","elem") and bt[1][0] in ("bytes","string") and member=="length": return ("elem",("uint",0))
        if bt[0]=="elem" and bt[1][0] in ("address","address_payable"):
            if member=="balance": return ("elem",("uint",0))
            if member=="code": return ("elemloc",("bytes",),"memory")
            if member=="codehash": return ("elem",("fixedbytes",32))
            return None
        if bt[0]=="custom":
            ent=bt[1]
            if isinstance(ent,Ent) and ent.cat=="struct":
                for f in ent.fields:
                    if f.name and f.name.name==member: return self.var_ty(f)
                self.dcx.emit(Diag("error",f"member `{member}` not found on type `{self.display_found(bt)}`",spans=[sd(e.ekind[2].span)])); return None
            if isinstance(ent,Ent) and ent.cat=="contract":
