    def infer_call(self,e):
        callee=e.ekind[1]; args_node=e.ekind[2]
        arg_types=[self.infer(a) for a in args_node.args]
        if getattr(args_node,"named",None):
            for nm,v in args_node.named: self.infer(v)
        # Type conversion: callee is Type expr
        if callee.ekind[0]=="Type":
            target=self.from_hir_ty(callee.ekind[1])
            if arg_types:
                src=arg_types[0]
                if not self.conversion_ok(target,src):
                    self.dcx.emit(Diag("error","invalid explicit type conversion",spans=[SpanData(e.span[0],e.span[1],e.span[2],f"cannot convert `{self.display_found(src)}` to `{self.display_found(target)}`",True)]))
            return target
        if callee.ekind[0]=="New":
            return self.from_hir_ty(callee.ekind[1])
        ct=self.infer(callee)
        # builtin functions
        if callee.ekind[0]=="Ident" and callee.ekind[1] and callee.ekind[1][0][0]=="builtin":
            return self.call_builtin(callee.ekind[1][0][1],args_node,arg_types,e)
        if ct is not None and ct[0]=="builtinfn":
            return ("elemloc",("bytes",),"memory")
        # User function(s)
        cands=[]
        if callee.ekind[0]=="Ident":
            for kind,val in callee.ekind[1]:
                if kind=="item" and isinstance(val,Ent) and val.cat=="function": cands.append(val)
        elif callee.ekind[0]=="Member":
            # resolve member function via base contract if base is This/contract ident/super - approximate via name search in all contracts
            mname=callee.ekind[2].name
            # If base inferred as custom contract, look in it and bases
            bt=self.infer(callee.ekind[1]) if False else None
            for f in self.hir.functions:
                if f.name and f.name.name==mname: cands.append(f)
        if cands:
            cand=None
            for f in cands:
                if len(f.parameters)==len(arg_types): cand=f; break
            if cand is None: cand=cands[0]
            for av,at in zip(cand.parameters,arg_types):
                # span of arg expr
                idx=list(cand.parameters).index(av)
                self.check_assign(args_node.args[idx].span,self.var_ty(av),at)
            if len(cand.returns)==1: return self.var_ty(cand.returns[0])
            if len(cand.returns)>1: return ("tuple",[self.var_ty(v) for v in cand.returns])
            return None
        return None
    def conversion_ok(self,target,src):
        if src is None or target is None: return True
        if self.compatible(target,src): return True
        # numeric to numeric conversions are allowed explicitly (except literal->address observed invalid because compatible() returns False and literal special) 
        if src[0]=="intlitval": return False
        if target[0]=="elem" and src[0]=="elem":
            nums={"uint","int","fixedbytes","address","address_payable","bool"}
            return target[1][0] in nums and src[1][0] in nums
        return False
    def call_builtin(self,name,args_node,arg_types,e):
        B=("elem",("bool",)); U=("elem",("uint",0)); B32=("elem",("fixedbytes",32)); ADDR=("elem",("address",)); BYTESMEM=("elemloc",("bytes",),"memory")
        sigs={
         "Assert":([B],None),"Require":([B],None),"RequireMsg":([B,("strlit",0)],None),"Revert":([],None),"RevertMsg":([("strlit",0)],None),
         "Keccak256":([BYTESMEM],B32),"Sha256":([BYTESMEM],B32),"Ripemd160":([BYTESMEM],("elem",("fixedbytes",20))),
         "EcRecover":([B32,("elem",("uint",8)),B32,B32],ADDR),"AddMod":([U,U,U],U),"MulMod":([U,U,U],U),
         "Gasleft":([],U),"Blockhash":([U],B32),"Blobhash":([U],B32),"Selfdestruct":([("elem",("address_payable",))],None),
        }
        if name not in sigs: return None
        params,ret=sigs[name]
        # Require/Revert overload by arg count handled by first Res (Require/Revert) - choose by count
        if name=="Require" and len(arg_types)>1: params,ret=sigs["RequireMsg"]
        if name=="Revert" and len(arg_types)>0: params,ret=sigs["RevertMsg"]
        for i,(pt,at) in enumerate(zip(params,arg_types)):
            if pt==("strlit",0):
                continue
            if not self.compatible(pt,at):
                # Original uses strlit display size 32 in some call contexts; use found display but adjust
                found=self.display_found(at)
                self.err_mismatch(args_node.args[i].span,self.display_expected(pt),found)
        return ret

def run_typeck_impl(compiler,hir):
    if hir is None: return
    Typeck(compiler,hir).run()

