# ============================= Span visitor & AST stats =============================
class SpanCollector:
    def __init__(self):
        self.spans=[]
    def add(self,span):
        if span is not None and span[1]>=0: self.spans.append(span)
    def id(self,x):
        if x is not None: self.add(x.span)
    def item(self,item):
        self.add(item.span)
        for d in item.docs:
            self.add(d.span)
            for ns in d.natspec: self.add(ns.span)
        self.item_kind(item.item)
    def item_kind(self,n):
        k=n.kind
        if k=="Pragma":
            mode=n.tokens[0]
            if mode=="Version":
                self.id(n.tokens[1]); req=n.tokens[2]
                for con in (req.dis if req else []):
                    self.add(con.span)
                    for comp in con.components:
                        self.add(comp.span)
                        if comp.ckind[0]=="Op": self.add(comp.ckind[2].span)
                        else: self.add(comp.ckind[1].span); self.add(comp.ckind[2].span)
            elif mode=="Custom":
                self.id(n.tokens[1]); self.id(n.tokens[2])
            else:
                for t in getattr(n,"raw_toks",[]): self.add(span_of(t))
        elif k=="Import":
            self.add(span_of(n.path_tok))
            if n.items[0]=="Plain": self.id(n.items[1])
            elif n.items[0]=="Glob": self.id(n.items[1])
            elif n.items[0]=="Select":
                for nm,al in n.items[1]: self.id(nm); self.id(al)
        elif k=="Contract":
            self.id(n.name)
            if n.layout: self.add(n.layout.span); self.expr(n.layout.slot)
            for b in n.bases: self.modifier(b)
            for sub in n.body: self.item(sub)
        elif k=="Function":
            self.func_header(n.header)
            if n.body: self.block(n.body)
            self.add(n.body_span)
        elif k=="VariableDefinition":
            self.var_def(n)
        elif k=="Struct":
            self.id(n.name)
            for f in n.fields: self.var_def(f)
        elif k=="Enum":
            self.id(n.name)
            for v in n.variants: self.id(v)
        elif k=="Udvt":
            self.id(n.name); self.ty(n.ty)
        elif k=="ErrorDef":
            self.id(n.name); self.param_list(n.parameters)
        elif k=="Event":
            self.id(n.name); self.param_list(n.parameters)
        elif k=="Using":
            if n.first[0]=="path":
                for x in n.first[1]: self.id(x)
            else:
                for parts,alias,op in n.first[1]:
                    for x in parts: self.id(x)
            if n.ty: self.ty(n.ty)
    def modifier(self,m):
        for x in m.name: self.id(x)
        self.call_args(m.arguments)
    def call_args(self,args):
        if args is None: return
        for a in args.args: self.expr(a)
        if getattr(args,"named",None):
            for nm,v in args.named: self.id(nm); self.expr(v)
        self.add(args.span)
    def func_header(self,h):
        self.add(h.span); self.id(h.name); self.param_list(h.parameters)
        if h.visibility: self.add(h.visibility[1])
        if h.state_mutability: self.add(h.state_mutability[1])
        for m in h.modifiers: self.modifier(m)
        if h.virtual: self.add(h.virtual)
        if h.override:
            self.add(h.override.span)
            for p in h.override.paths:
                for x in p: self.id(x)
        if h.returns: self.param_list(h.returns)
    def param_list(self,pl):
        if pl is None: return
        for v in pl.vars: self.var_def(v)
        self.add(pl.span)
    def var_def(self,v):
        self.add(v.span); self.ty(v.ty); self.id(v.name)
        if v.initializer: self.expr(v.initializer)
    def ty(self,t):
        if t is None: return
        self.add(t.span); tk=t.tkind
        if tk[0]=="array":
            self.ty(tk[1])
            if tk[2] is not None: self.expr(tk[2])
        elif tk[0]=="mapping":
            self.ty(tk[1]); self.id(tk[2]); self.ty(tk[3]); self.id(tk[4])
        elif tk[0]=="custom":
            for x in tk[1]: self.id(x)
        elif tk[0]=="function":
            _,params,vis,mut,rets=tk
            self.param_list(params)
            if vis: self.add(vis[1])
            if mut: self.add(mut[1])
            if rets: self.param_list(rets)
    def block(self,b):
        self.add(b.span)
        for s in b.stmts: self.stmt(s)
    def stmt(self,s):
        self.add(s.span)
        for d in getattr(s,"docs",[]):
            self.add(d.span)
            for ns in d.natspec: self.add(ns.span)
        sk=s.skind; t=sk[0]
        if t=="Block": self.block(sk[1])
        elif t=="Unchecked": self.block(sk[1])
        elif t=="Expr": self.expr(sk[1])
        elif t=="VarDecl":
            for v in sk[1]: self.var_def(v)
        elif t=="VarDeclTuple":
            for v in sk[1]:
                if v is not None: self.var_def(v)
            self.expr(sk[2])
        elif t=="If":
            self.expr(sk[1]); self.stmt(sk[2])
            if sk[3]: self.stmt(sk[3])
        elif t=="While": self.expr(sk[1]); self.stmt(sk[2])
        elif t=="DoWhile": self.stmt(sk[1]); self.expr(sk[2])
        elif t=="For":
            if sk[1]: self.stmt(sk[1])
            if sk[2]: self.expr(sk[2])
            if sk[3]: self.expr(sk[3])
            self.stmt(sk[4])
        elif t=="Return":
            if sk[1] is not None: self.expr(sk[1])
        elif t=="EmitPath":
            for x in sk[1]: self.id(x)
            self.call_args(sk[2])
        elif t=="Revert":
            for x in sk[1]: self.id(x)
            self.call_args(sk[2])
        elif t=="Assembly":
            _,dialect,flags,blk=sk
            if dialect: self.add(dialect.span)
            for f in flags: self.add(f.span)
            self.yul_block(blk)
        elif t=="Try":
            self.expr(sk[1])
            for c in sk[2]:
                self.add(c.span); self.id(c.name)
                if c.args: self.param_list(c.args)
                self.block(c.block)
    def expr(self,e):
        if e is None: return
        self.add(e.span); ek=e.ekind; t=ek[0]
        if t=="Lit": self.add(ek[1].span)
        elif t=="Ident": self.id(ek[1])
        elif t=="Binary": self.expr(ek[1]); self.add(ek[3]); self.expr(ek[4])
        elif t=="Assign": self.expr(ek[1]); self.add(ek[3]); self.expr(ek[4])
        elif t=="Ternary": self.expr(ek[1]); self.expr(ek[2]); self.expr(ek[3])
        elif t=="Unary": self.add(ek[2]); self.expr(ek[3])
        elif t=="Delete": self.expr(ek[1])
        elif t=="Member": self.expr(ek[1]); self.id(ek[2])
        elif t=="Call": self.expr(ek[1]); self.call_args(ek[2])
        elif t=="CallOptions":
            self.expr(ek[1])
            for nm,v in ek[2]: self.id(nm); self.expr(v)
        elif t=="Index":
            self.expr(ek[1])
            if ek[2] is not None: self.expr(ek[2])
        elif t=="Slice":
            self.expr(ek[1])
            if ek[2] is not None: self.expr(ek[2])
            if ek[3] is not None: self.expr(ek[3])
        elif t=="Tuple":
            for x in ek[1]:
                if x is not None: self.expr(x)
        elif t=="ArrayLit":
            for x in ek[1]: self.expr(x)
        elif t in ("New","Type","ElemType"): self.ty(ek[1])
        elif t=="Payable": self.call_args(ek[1])
    def yul_block(self,b):
        self.add(b.span)
        for s in b.stmts: self.yul_stmt(s)
    def yul_stmt(self,s):
        self.add(s.span)
        for d in getattr(s,"docs",[]):
            self.add(d.span)
            for ns in d.natspec: self.add(ns.span)
        sk=s.skind; t=sk[0]
        if t=="Block": self.yul_block(sk[1])
        elif t=="VarDecl":
            for v in sk[1]: self.id(v)
            if sk[2]: self.yul_expr(sk[2])
        elif t=="AssignSingle":
            for x in sk[1]: self.id(x)
            self.yul_expr(sk[2])
        elif t=="AssignMultiple":
            for p in sk[1]:
                for x in p: self.id(x)
            self.yul_expr(sk[2])
        elif t=="Expr": self.yul_expr(sk[1])
        elif t=="If": self.yul_expr(sk[1]); self.yul_block(sk[2])
        elif t=="Switch":
            self.yul_expr(sk[1])
            for entry in sk[2]:
                self.add(entry[3])
                if entry[1] is not None: self.yul_expr(entry[1])
                self.yul_block(entry[2])
        elif t=="For": self.yul_block(sk[1]); self.yul_expr(sk[2]); self.yul_block(sk[3]); self.yul_block(sk[4])
        elif t=="FunctionDef":
            _,name,params,rets,blk=sk
            self.id(name)
            for x in params: self.id(x)
            for x in rets: self.id(x)
            self.yul_block(blk)
    def yul_expr(self,e):
        self.add(e.span); ek=e.ekind; t=ek[0]
        if t=="Lit": self.add(ek[1].span)
        elif t=="Path":
            for x in ek[1]: self.id(x)
        elif t=="Call":
            self.id(ek[1])
            for a in ek[2]: self.yul_expr(a)

def do_span_visitor_impl(compiler):
    for src in compiler.sources:
        if src.ast is None and src.yul_ast is None: continue
        col=SpanCollector()
        if src.yul_ast is not None:
            # Yul objects/blocks span visiting is not Solidity AST - span visitor likely does nothing for Yul sources
            continue
        for item in src.ast or []:
            col.item(item)
        for i,span in enumerate(col.spans,1):
            compiler.dcx.emit(Diag("note",f"span #{i}",spans=[sd(span)]))

def do_ast_stats_impl(compiler):
    # Best-effort implementation of the original's AST stats visitor.
    sizes={"DocComments":8,"Span":8,"SourceUnit":16,"DocComment":24,"Item":160,"ItemContract":48,"ItemFunction":144,"VariableDefinition":72,"ItemStruct":24,"ItemEnum":24,"ItemUdvt":40,"ItemError":32,"ItemEvent":32,"PragmaDirective":32,"ImportDirective":32,"UsingDirective":48,"Block":16,"Stmt":64,"Expr":48,"Lit":88,"Ident":12,"ParameterList":16,"CallArgs":24,"Modifier":32,"PathSlice":12,"TryCatchClause":56,"StmtTry":16,"StmtAssembly":40,"YulBlock":16,"YulExprCall":24}
    counts={}; variants={}
    def add(name):
        if name in sizes: counts[name]=counts.get(name,0)+1
    def addvar(parent,name):
        variants.setdefault(parent,{})[name]=variants.setdefault(parent,{}).get(name,0)+1
    # Traverse using span collector-like logic but counting node types.
    stats=AstStatsCollector(counts,variants,add,addvar)
    any_ast=False
    for src in compiler.sources:
        if src.ast is None: continue
        any_ast=True; add("SourceUnit")
        for item in src.ast: stats.item(item)
    if not any_ast:
        return
    if stats.span_count: counts["Span"]=stats.span_count
    rows=[]
    total=0
    for name,sz in sizes.items():
        c=counts.get(name,0)
        if c: rows.append((name,c*sz,c,sz)); total+=c*sz
    # Variant subrows do not add to total (they recount parent size) - but in original, are they included in Total? Example contract C{}: rows sum: 8+8+16+48+160=240 = Total, and - Contract 160 is NOT added. Good.
    rows.sort(key=lambda r:(r[1],r[0]))
    out=[]
    out.append("ast-stats AST STATS")
    out.append("ast-stats Name                Accumulated Size         Count     Item Size")
    out.append("ast-stats ----------------------------------------------------------------")
    def fmt_num(n):
        s=str(n)
        # Rust Display for a custom ByteSize? It used underscores for >=1000 in big example (1_008). Format groups of 3 with _ for accumulated and total.
        return f"{n:,}".replace(",","_")
    for name,acc,c,sz in rows:
        pct=(acc/total*100) if total else 0
        out.append(f"ast-stats {name:<20} {fmt_num(acc):>10} ({pct:4.1f}%) {c:>13} {sz:>13}")
        if name in variants:
            parent_size=sizes[name]
            vrows=sorted(variants[name].items(),key=lambda kv:(kv[1]*parent_size,kv[0]))
            for vname,vc in vrows:
                vacc=vc*parent_size; vpct=(vacc/total*100) if total else 0
                out.append(f"ast-stats {'- '+vname:<20} {fmt_num(vacc):>10} ({vpct:4.1f}%) {vc:>13} ")
    out.append("ast-stats ----------------------------------------------------------------")
    out.append(f"ast-stats Total                    {fmt_num(total)}")
    out.append("ast-stats")
    sys.stderr.write("\n".join(out)+"\n"); sys.stderr.flush()

class AstStatsCollector:
    def __init__(self,counts,variants,add,addvar):
        self.counts=counts; self.variants=variants; self.add=add; self.addvar=addvar; self.span_count=0
    def span(self): self.span_count+=1
    def item(self,item):
        self.add("Item"); self.span()
        self.docs(item.docs)
        n=item.item
        vmap={"Contract":"Contract","Function":"Function","VariableDefinition":"Variable","Struct":"Struct","Enum":"Enum","Udvt":"Udvt","ErrorDef":"Error","Event":"Event","Pragma":"Pragma","Import":"Import","Using":"Using"}
        if n.kind in vmap: self.addvar("Item",vmap[n.kind])
        kmap={"Contract":"ItemContract","Function":"ItemFunction","Struct":"ItemStruct","Enum":"ItemEnum","Udvt":"ItemUdvt","ErrorDef":"ItemError","Event":"ItemEvent","Pragma":"PragmaDirective","Import":"ImportDirective","Using":"UsingDirective"}
        if n.kind in kmap: self.add(kmap[n.kind])
        self.item_kind(n)
    def docs(self,docs):
        self.add("DocComments")
        for d in docs: self.add("DocComment")
    def item_kind(self,n):
        k=n.kind
        if k=="Contract":
            for sub in n.body: self.item(sub)
        elif k=="Function":
            # signature var defs are not counted as VariableDefinition; types may contain exprs
            if n.body: self.block(n.body)
        elif k=="VariableDefinition":
            self.add("VariableDefinition")
            if n.initializer: self.expr(n.initializer)
        elif k=="Struct":
            for f in n.fields: self.add("VariableDefinition")
        elif k=="Enum":
            for v in n.variants: self.add("Ident")
        elif k in ("ErrorDef","Event"):
            self.add("ParameterList"); self.span()
            for v in n.parameters.vars: self.add("VariableDefinition")
    def block(self,b):
        self.add("Block"); self.span()
        for s in b.stmts: self.stmt(s)
    def stmt(self,s):
        self.add("Stmt"); self.span()
        self.docs(getattr(s,"docs",[]))
        sk=s.skind; t=sk[0]
        vname={"VarDecl":"DeclSingle","VarDeclTuple":"DeclMulti","Unchecked":"UncheckedBlock","EmitPath":"Emit","Revert":"Revert"}.get(t,t)
        self.addvar("Stmt",vname)
        if t=="Block": self.block(sk[1])
        elif t=="Unchecked": self.block(sk[1])
        elif t=="Expr": self.expr(sk[1])
        elif t=="VarDecl":
            self.add("VariableDefinition")
            # Span for counted VarDef is not added (matching small examples where initializer Expr contributes)
            if sk[1][0].initializer: self.expr(sk[1][0].initializer)
        elif t=="VarDeclTuple":
            for v in sk[1]:
                if v is not None: self.add("VariableDefinition")
            self.expr(sk[2])
        elif t=="If":
            self.expr(sk[1]); self.stmt(sk[2])
            if sk[3]: self.stmt(sk[3])
        elif t=="While": self.expr(sk[1]); self.stmt(sk[2])
        elif t=="DoWhile": self.stmt(sk[1]); self.expr(sk[2])
        elif t=="For":
            if sk[1]: self.stmt(sk[1])
            if sk[2]: self.expr(sk[2])
            if sk[3]: self.expr(sk[3])
            self.stmt(sk[4])
        elif t=="Return":
            if sk[1] is not None: self.expr(sk[1])
        elif t=="EmitPath": self.add("CallArgs"); self.span(); [self.expr(a) for a in sk[2].args]
        elif t=="Revert": self.add("CallArgs"); self.span(); [self.expr(a) for a in sk[2].args]
        elif t=="Try":
            self.add("StmtTry"); self.expr(sk[1])
            for c in sk[2]:
                self.add("TryCatchClause"); self.span()
                if c.args: self.add("ParameterList"); self.span()
                for v in ([] if not c.args else c.args.vars): self.add("VariableDefinition")
                self.block(c.block)
        elif t=="Assembly":
            self.add("StmtAssembly"); self.add("YulBlock"); self.span()
    def expr(self,e):
        if e is None: return
        self.add("Expr"); self.span()
        ek=e.ekind; t=ek[0]
        vname={"ArrayLit":"Array","ElemType":"Type","Type":"TypeCall"}.get(t,t)
        self.addvar("Expr",vname)
        if t=="Lit": self.add("Lit")
        elif t=="Ident": self.add("Ident")
        elif t=="Binary": self.expr(ek[1]); self.expr(ek[4])
        elif t=="Assign": self.expr(ek[1]); self.expr(ek[4])
        elif t=="Ternary": self.expr(ek[1]); self.expr(ek[2]); self.expr(ek[3])
        elif t=="Unary": self.expr(ek[3])
        elif t=="Delete": self.expr(ek[1])
        elif t=="Member": self.expr(ek[1])
        elif t=="Call":
            self.expr(ek[1]); self.add("CallArgs"); self.span()
            for a in ek[2].args: self.expr(a)
            if getattr(ek[2],"named",None):
                for nm,v in ek[2].named: self.expr(v)
        elif t=="CallOptions":
            self.expr(ek[1])
            for nm,v in ek[2]: self.expr(v)
        elif t=="Index":
            self.expr(ek[1])
            if ek[2] is not None: self.expr(ek[2])
        elif t=="Slice":
            self.expr(ek[1])
            if ek[2] is not None: self.expr(ek[2])
            if ek[3] is not None: self.expr(ek[3])
        elif t=="Tuple":
            for x in ek[1]:
                if x is not None: self.expr(x)
        elif t=="ArrayLit":
            for x in ek[1]: self.expr(x)
        elif t=="Payable":
            self.add("CallArgs"); self.span()
            for a in ek[1].args: self.expr(a)

